/* font-family:'Pretendard' */
@font-face {
    font-family: 'Pretendard';
    font-weight: 100;
    font-style: normal;
    src: url('../../fonts/Pretendard-Thin.eot');
    src: url('../../fonts/Pretendard-Thin.eot?#iefix') format('embedded-opentype'),
        url('../../fonts/Pretendard-Thin.woff2') format('woff2'), url('../../fonts/Pretendard-Thin.woff') format('woff'),
        url('../../fonts/Pretendard-Thin.ttf') format('truetype'), url('../../fonts/Pretendard-Thin.svg') format('svg');
    font-display: swap;
}
