    // screen2 step3 - 초기
    .sr-step-swiper-wrap {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    .sr-step-swiper-wrap {
        .sr-step-swiper-inner {
            .bg-backgroung-blur-wrap {
                position: absolute;
                width: 100%;
                height: 100%;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                .bg-backgroung-blur-inner {
                    position: relative;
                    width: inherit;
                    height: inherit;
                    .bg-backgroung-blur-layer {
                        background-position: center center;
                        background-repeat: no-repeat;
                        background-size: contain;
                    }
                }
            }
            .top-swiper-text {
                text-align: center;
            }
        }
        .sr-step-swiper-box-wrap {
        }
    }

    .top-swiper-text {
        + .swiper-layer-wrap {
            margin-top: 32px;
        }
    }
    .swiper-title-wrap {
        .slick-list {
            width: 960px;
            margin-left: auto;
            margin-right: auto;
        }
        + .swiper-layer-wrap {
            margin-top: 32px;
        }
    }
    .swiper-layer-wrap {
        position: relative;
        margin-left: auto;
        margin-right: auto;
        .slick-arrow {
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            width: 64px;
            height: 64px;
            background-color: rgba(255, 255, 255, 0.2);
            border-radius: 50%;
            background-repeat: no-repeat;
            background-size: 11px 23px;
            background-position: center center;
            font-size: 0;
            text-indent: -9999px;
            transition-duration: 0.3s;
            &:hover {
                background-color: rgba(255, 255, 255, 0.1);
            }
            &.slick-prev {
                left: calc(50% - 560px);
                background-image: url('../../images/ko/showroom/srcomm/icon-slick-prev.png');
            }
            &.slick-next {
                right: calc(50% - 560px);
                background-image: url('../../images/ko/showroom/srcomm/icon-slick-next.png');
            }
        }
        .slick-list {
            width: 960px;
            height: 540px;
            margin-left: auto;
            margin-right: auto;
            .slick-track {
                height: 100%;
                cursor: grab;
                .swiper-layer-item {
                    position: relative;
                    height: 100%;
                    background-color: rgba(0, 0, 0, 1);
                    .video-iframe {
                        display: none;
                        width: 100%;
                        height: 100%;
                        &.active {
                            display: block;
                        }
                    }
                }
            }
            ~ .slick-dots {
                margin-top: 30px;
            }
        }
        .slick-dots {
            font-size: 0;
            text-align: center;
            > li {
                display: inline-block;
                font-size: 0;
                width: 8px;
                height: 8px;
                border-radius: 50%;
                margin-left: 4px;
                margin-right: 4px;
                &.slick-active {
                    > button {
                        background-color: rgba(29, 108, 235, 1);
                    }
                }
                > button {
                    width: inherit;
                    height: inherit;
                    font-size: 0;
                    text-indent: -9999px;
                    background-color: rgba(196, 196, 196, 1);
                    border-radius: 50%;
                }
            }
        }
        ~ .bottom-swiper-button-wrap {
            margin-top: 42px;
        }
    }

    .title-step-swiper {
        display: block;
        font-size: 0;
        .text {
            display: inline-block;
            font-family: 'Pretendard';
            font-size: 32px;
            font-weight: 400;
            line-height: 42px;
            letter-spacing: -0.3px;
            color: rgba(255, 255, 255, 1);
            .bold {
                font-size: 32px;
                font-weight: 700;
                letter-spacing: -0.3px;
                color: rgba(255, 255, 255, 1);
            }
        }
        + .sub-text-step-swiper {
            margin-top: 10px;
        }
    }

    .sub-text-step-swiper {
        display: block;
        font-size: 0;
        .text {
            display: inline-block;
            font-family: 'Pretendard';
            font-size: 18px;
            font-weight: 400;
            line-height: 30px;
            letter-spacing: -0.3px;
            color: rgba(255, 255, 255, 1);
        }
    }

    .bottom-swiper-button-wrap {
        text-align: center;
        font-size: 0;
    }

    .button-swiper-bottom {
        min-width: 210px;
        font-size: 0;
        text-align: center;
        background-color: rgba(29, 108, 235, 1);
        padding: 12px;
        border-radius: 4px;
        .text {
            display: inline-block;
            font-family: 'Pretendard';
            font-weight: 500;
            font-size: 20px;
            line-height: 26px;
            letter-spacing: 0;
            color: rgba(255, 255, 255, 1);
        }
    }

    .thumbnail-wrap {
        position: absolute;
        width: 100%;
        height: 100%;
        top: 0;
        left: 0;
        z-index: 1;
        background-repeat: no-repeat;
        background-size: 100% 100%;
        background-position: center center;
        background-color: rgba(0, 0, 0, 0.3);
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        transition-duration: 0.3s;
        &.active {
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
        .thumbnail-inner {
            position: relative;
            width: inherit;
            height: inherit;
        }
        .button-movie-start {
            position: absolute;
            width: 97px;
            height: 97px;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            border-radius: 50%;
            background-color: rgba(0, 0, 0, 0.7);
            background-repeat: no-repeat;
            background-size: 30px 34px;
            background-position: center center;
            background-image: url('../../images/ko/showroom/srcomm/btn-layer-movie-play.png');
        }
    }
}
