    }

    background-color: rgba(226, 226, 226, 1);

    // 우측 스텝 메뉴 초기셋팅
    .service-step-wrap {
        opacity: 0;
        visibility: hidden;
        top: 52%;
        .service-step-inner {
            &::after {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                display: block;
                content: '';
                background-repeat: no-repeat;
                background-position: center center;
                background-size: 100% 100%;
                // background-image: url('../../images/ko/showroom/sr3/bg-sr3-dimm1-3-1.png');
                background-color: rgba(0, 0, 0, 0.75);
                filter: blur(0px);
                transition-delay: 0s;
                transition-duration: 0s;
                opacity: 0;
                visibility: hidden;
                border-radius: 20px;
                pointer-events: none;
            }
        }
    }

    // [매장] 컨텐츠 showroom-content-wrap5
    .showroom-content-wrap5 {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;
    }

    // 스크린 공통
    .showroom-screen-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    // 스텝 공통
    .showroom-step-wrap {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 100%;
        height: 100%;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    // 스텝 안 공통
    .showroom-step-inner {
        position: relative;
        width: 100%;
        height: 100%;
    }

