    .showroom-background {
        // 이미지
        &-area {
            position: absolute;
            width: 1920px;
            height: 1080px;
            top: 50%;
            left: 50%;
        }
        &-inner {
            position: relative;
            width: inherit;
            height: inherit;
        }
        // 배경 인테리어
        &-layer {
            position: absolute;
            top: -45.96px;
            left: 47.56px;
            width: 2121.11px;
            height: 1175px;
            background-image: url('../../images/ko/showroom/sr5/bg-sr5-interior0-1.jpg');
            transform: scale(1);
            opacity: 0;
            visibility: hidden;
        }
        // 딤 : 배경 어둠/밝기
        &-dim {
            background-image: url('../../images/ko/showroom/sr5/bg-sr5-dimm0-1.png');
            opacity: 0;
            visibility: hidden;
        }
    }

