// [창고] : /showroom/storage.html

.sr6-storage {
    // [창고] .sr6-storage Start
    background-color: rgba(226, 226, 226, 1);

    // 기본 셋팅
    .showroom-screen-wrap {
        opacity: 0;
        visibility: hidden;
        .showroom-step-wrap {
            opacity: 0;
            visibility: hidden;
        }
    }

    // 우측 스텝 메뉴 초기셋팅
    .service-step-wrap {
        opacity: 0;
        visibility: hidden;
        top: 52%;
        .service-step-inner {
            &::after {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                display: block;
                content: '';
                background-repeat: no-repeat;
                background-position: center center;
                background-size: 100% 100%;
                background-color: rgba(0, 0, 0, 0.75);
                filter: blur(0px);
                transition-delay: 0s;
                transition-duration: 0s;
                opacity: 0;
                visibility: hidden;
                border-radius: 20px;
                pointer-events: none;
            }
        }
    }

    // [창고] 컨텐츠 showroom-content-wrap6
    .showroom-content-wrap6 {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;
    }

    // 배경 : 인테리어, 딤 기본설정
    .showroom-background {
        // 이미지
        &-area {
            position: absolute;
            width: 1920px;
            height: 1080px;
            top: 50%;
            left: 50%;
        }
        &-inner {
            position: relative;
            width: inherit;
            height: inherit;
        }
        // 배경 인테리어
        &-layer {
            position: absolute;
            right: -10px;
            bottom: -6px;
            width: 1930px;
            height: 1086px;
            background-image: url('../../images/ko/showroom/sr6/bg-sr6-interior0-1.jpg');
            transform: scale(1);
            opacity: 0;
            visibility: hidden;
        }
        // 딤 : 배경 어둠/밝기
        &-dim {
            background-image: url('../../images/ko/showroom/sr6/bg-sr6-dimm0-1.png');
            opacity: 0;
            visibility: hidden;
        }
    }

    // 타겟팅 - 초기
    .sr-targeting {
        position: absolute;
        top: 493.17px;
        left: 458.38px;
        transform: scale(0);
    }

    // 안심
    .popup-check-complete-wrap {
        position: absolute;
        z-index: 25;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        width: 282px;
        height: 280px;
        &.popup-check-complete-wrap1 {
            top: 494.5px;
            left: 1190.75px;
            & .bg-check-complete {
                background-image: url('../../images/ko/showroom/sr6//bg-popup-sr6-completer-screen1.png');
            }
        }
        &.popup-check-complete-wrap2 {
            top: 223px;
            left: 745.3px;
            & .bg-check-complete {
                background-image: url('../../images/ko/showroom/sr6//bg-popup-sr6-completer-screen2.png');
            }
        }
        &.popup-check-complete-wrap3 {
            top: 473px;
            left: 299.87px;
            & .bg-check-complete {
                background-image: url('../../images/ko/showroom/sr6//bg-popup-sr6-completer-screen3.png');
            }
        }
        &.check-complete {
            transition-delay: 1s;
            transition-duration: 1s;
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
    }

    // screen1 step1
    .sr-speech-sc1-st1 {
        // 말풍선
        position: absolute;
        top: 205.33px;
        left: 481.01px;
        opacity: 0;
        visibility: hidden;
    }

    .sr-speech-sr1-st1-1 {
        // 말풍선
        position: absolute;
        top: 321px;
        left: 967.27px;
        opacity: 0;
        visibility: hidden;
    }

    .sr-person-sc1-st1 {
        // 사람
        @include bgCenterSet;
        background-image: url('../../images/ko/showroom/sr6/item-sr6-worker-storage1.svg');
        position: absolute;
        top: 407px;
        left: 782px;
        width: 274px;
        height: 480.94px;
        opacity: 0;
        visibility: hidden;
    }

    // screen1 step2
    .showroom-screen1-wrap {
        // screen1 - step2 아이콘 초기
        .showroom-step2-icon-layer-wrap {
            position: absolute;
            top: 277px;
            left: 212px;
            width: 1163.2px;
            height: 339.89px;
            .showroom-step2-icon-layer-inner {
                position: relative;
                width: 100%;
                height: 100%;
                .sr-circle-item {
                    position: absolute;
                    opacity: 0;
                    visibility: hidden;
                    .sr-circle-item-inner {
                        position: relative;
                    }
                    &.sr-circle-item1 {
                        top: 180px;
                        left: 0px;
                        & .img-secom-circle-item1 {
                            background-size: 24px 45px;
                            background-image: url(../../images/ko/showroom/sr6/item-sr6-circle-item1.png);
                        }
                    }
                    &.sr-circle-item2 {
                        top: 0;
                        left: 214px;
                        & .img-secom-circle-item2 {
                            background-size: 80px 80px;
                            background-image: url(../../images/ko/showroom/sr6/item-sr6-circle-item2.png);
                        }
                    }
                    &.sr-circle-item3 {
                        top: 304px;
                        left: 261px;
                        & .img-secom-circle-item3 {
                            background-size: 54px 22px;
                            background-image: url(../../images/ko/showroom/sr6/item-sr6-circle-item3.png);
                        }
                    }
                    &.sr-circle-item4 {
                        top: 393px;
                        left: 593px;
                        & .img-secom-circle-item4 {
                            background-size: 53px 38px;
                            background-image: url(../../images/ko/showroom/sr6/item-sr6-circle-item4.png);
                        }
                    }
                    &.sr-circle-item5 {
                        top: 0px;
                        left: 744px;
                        & .img-secom-circle-item5 {
                            background-size: 34.667px 42.158px;
                            background-image: url(../../images/ko/showroom/sr6/item-sr6-circle-item5.png);
                        }
                    }
                    &.sr-circle-item6 {
                        top: 268.89px;
                        left: 1083.2px;
                        & .img-secom-circle-item6 {
                            background-size: 57px 77px;
                            background-image: url(../../images/ko/showroom/sr6/item-sr6-circle-item6.png);
                        }
                    }
                    [data-tooltip-wrap] {
                        [data-tooltip] {
                            top: 14.46px;
                        }
                    }
                }
            }
        }
    }

    // screen1 step3 공통
    .sr-warning-red-wrap {
        // 경고문구 공통
        .sr-warning-red {
            opacity: 0;
            visibility: hidden;
            transition-duration: 0.6s;
            display: inline-block;
            position: absolute;
            z-index: 10;
            > p {
                font-size: 18px;
                font-weight: 700;
                border-radius: 50px;
                padding: 10px 18px;
                color: #fff;
                background-color: #c8001e;
                i {
                    background: url('../../images/ko/showroom/srcomm/icon-warning.png') no-repeat 50% / 24px 24px;
                    display: inline-block;
                    vertical-align: middle;
                    width: 24px;
                    height: 24px;
                    margin-right: 5px;
                    margin-bottom: 2px;
                }
            }
            &.sr-warning-red1 {
                top: 500px;
                left: 510.87px;
            }
            &.sr-warning-red2 {
                top: 176px;
                left: 511.65px;
            }
            &.sr-warning-red3 {
                top: 292px;
                left: 736px;
            }
        }
    }
    .sr-magnet-sensor {
        // 자석 감지기 제품 공통
        @include bgCenterSet;
        background-image: url('../../images/ko/showroom/sr6/img-magnet-sensor.svg');
        position: absolute;
        top: 557px;
        left: 253px;
        width: 295px;
        height: 168px;
        opacity: 0;
        visibility: hidden;
    }
    .sr-thief-house {
        // 강도
        display: inline-block;
        background-repeat: no-repeat;
        background-position: center center;
        background-size: contain;
        position: absolute;
        opacity: 0;
        visibility: hidden;
    }
    // screen1 step3 step-2
    .sr-moving-sensor {
        // 움직임 감지기 제품 공통
        @include bgCenterSet;
        background-image: url('../../images/ko/showroom/sr6/icon-heat-detector.svg');
        position: absolute;
        top: 43.7px;
        left: 332.85px;
        width: 31.81px;
        height: 65.41px;
        opacity: 0;
        visibility: hidden;
    }
    .sr-layer-beam-sr6-st3 {
        position: absolute;
        width: 600px;
        height: 661px;
        top: 61.75px;
        left: 351px;
        transform-origin: 0 0;
        transform: scale(1.5) rotate(6deg);
        opacity: 0;
        visibility: hidden;
        font-size: 0;
    }
    // screen1 step3 step-3
    .sr-infrared-sensor {
        // 움직임 감지기 제품
        @include bgCenterSet;
        background-image: url('../../images/ko/showroom/sr6/img-infrared-sensor.png');
        position: absolute;
        top: 254.2px;
        left: 34px;
        width: 1366.6px;
        height: 561.8px;
        z-index: 1;
        opacity: 0;
        visibility: hidden;
    }
    .sr-spread-wave {
        // 움직임 감지기 전파
        @include bgCenterSet;
        background-image: url('../../images/ko/showroom/sr6/img-spread-wave.png');
        position: absolute;
        top: 170.37px;
        left: -63.5px;
        width: 1502.75px;
        height: 729.97px;
        opacity: 0;
        visibility: hidden;
        transform: scale(0);
    }

    // screen1 step3 step-4,step-5
    .popup-layer-animation-wrap {
        // 팝업
        position: absolute;
        opacity: 0;
        visibility: hidden;
        top: 52%;
        left: 50%;
        transform: translate(-50%, -50%);
        z-index: 2;
        transition-duration: 0s;
    }

    // screen1 step3 step-5
    .showroom-product-wrap {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        transform: translate3d(-50%, -50%, 0px) scale(1);
        position: absolute;
        z-index: 3;
        .showroom-product-inner {
            position: relative;
            width: 100%;
            height: 100%;
            .sr-sm-infrared-sensor {
                // 움직임 감지기 전파
                @include bgCenterSet;
                background-image: url('../../images/ko/showroom/sr6/img-sr6-pro3.svg');
                position: absolute;
                top: -162.11px;
                left: 833.2px;
                width: 493.92px;
                height: 558.58px;
                opacity: 0;
                visibility: hidden;
            }
        }
    }

    // 출동경비 서비스 0911 팝업
    .popup-layer-animation-wrap1 {
        &.popup-layer-animation-wrap {
            display: inline-block;
            border-radius: 20px;
            width: 820px;
            height: 490px;
            margin-left: auto;
            margin-right: auto;
            font-size: 0;

            .popup-layer-animation-inner {
                display: inline-block;
                position: relative;
                width: inherit;
                height: inherit;
                font-size: 0;
                border-radius: inherit;
                overflow: hidden;
                &::before {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    width: 120%;
                    height: 120%;
                    transform: translate(-50%, -50%);
                    display: block;
                    content: '';
                    background-color: rgba(36, 36, 36, 0.95);
                    filter: blur(10px);
                }
                .animation-box-wrap {
                    position: absolute;
                    top: 0;
                    left: 0;
                    right: 0;
                    height: 318px;
                    font-size: 0;
                    &.control-center {
                        .icon-postion-wrap {
                            position: absolute;
                            z-index: 1;
                            .icon-postion-inner {
                                position: relative;
                                .ani-icon-secom {
                                    position: relative;
                                    z-index: 1;
                                }
                                .ellipse-wave-length-wrap {
                                    left: 50%;
                                    transform: translateX(-50%);
                                    &.ellipse-wave-length-wrap1 {
                                        // bottom: -6px;
                                    }
                                    &.ellipse-wave-length-wrap2 {
                                        bottom: -14px;
                                    }
                                }
                            }
                            &.top-center {
                                top: 55.04px;
                                left: 50%;
                                transform: translateX(-50%);
                            }
                            &.bottom-left {
                                top: 185px;
                                left: 100px;
                            }
                            &.bottom-left-top {
                                top: 45px;
                                left: 160px;
                            }
                            &.bottom-center {
                                top: 179px;
                                left: 50%;
                                transform: translateX(-50%);
                                .ani-icon-name {
                                    bottom: -30px;
                                }
                            }
                            &.bottom-right-top {
                                top: 45px;
                                right: 160px;
                            }
                            &.bottom-right {
                                top: 186px;
                                right: 100px;
                            }
                            .ani-icon-name {
                                @include elHide();
                            }
                        }
                        .line-dot-red {
                            position: absolute;
                            display: inline-block;
                            bottom: 45px;
                            .line-dot-view {
                                display: inline-block;
                                background-repeat: repeat;
                                background-size: 10px 10px;
                                background-image: url('../../images/ko/showroom/srcomm/bg-line-dot-scarlet.png');
                            }
                            &.center-width {
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                                &.center-width-left {
                                    left: 200px;
                                }
                                &.center-width-right {
                                    right: 200px;
                                }
                                &.center-width-left-top {
                                    left: 247px;
                                    bottom: 185px;
                                    transform: rotate(41deg);
                                    transform-origin: 0 0;
                                }
                                &.center-width-right-top {
                                    right: 247px;
                                    bottom: 185px;
                                    transform: rotate(-41deg);
                                    transform-origin: 100% 0;
                                }
                            }
                            &.center-bottom-top {
                                left: 50%;
                                transform: translate(-50%);
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                            }
                        }
                    }
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            position: absolute;
                            width: 96px;
                            height: 184px;
                            .sr-person-dm-inner {
                                position: relative;
                                .icon-ex-mark-speech-bubble {
                                    position: absolute;
                                    top: -24.92px;
                                    right: -46.94px;
                                }
                            }
                        }
                        .img-dispatch-vehicle {
                            position: absolute;
                        }
                    }
                    .animation-box-inner {
                        position: relative;
                        width: 100%;
                        height: 100%;
                        > div:not(.top-center) {
                            width: 170px;
                            height: 100px;
                            display: flex;
                            align-items: flex-end;
                            justify-content: center;
                        }
                    }
                }
                .bottom-text-wrap {
                    display: block;
                    position: absolute;
                    left: 115px;
                    right: 115px;
                    text-align: center;
                    .text {
                        display: inline-block;
                        font-family: 'Pretendard';
                        font-size: 26px;
                        font-weight: 400;
                        line-height: 130%;
                        letter-spacing: -0.3px;
                        color: rgba(255, 255, 255, 1);
                        .color-blue {
                            font-family: 'Pretendard';
                            font-size: 26px;
                            font-weight: 700;
                            letter-spacing: -0.3px;
                            color: rgba(43, 158, 255, 1);
                        }
                    }
                }
            }

            .bottom-text-wrap {
                bottom: 0px;
                opacity: 0;
                visibility: hidden;
                transition-duration: 0.6s;
            }

            .animation-box-wrap {
                &.control-center {
                    .icon-postion-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                    }

                    .ellipse-wave-length-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                        .ellipse-wave-item {
                            animation-timing-function: linear;
                            animation-duration: 1s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                    }

                    .line-dot-red {
                        .line-dot-view {
                            animation-timing-function: linear;
                            animation-direction: normal;
                            animation-iteration-count: infinite;
                        }
                        &.center-width {
                            width: 0px;
                            height: 2px;
                            transition-duration: 0s;
                            &.center-width-left {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                            &.center-width-left-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                        }
                        &.center-bottom-top {
                            width: 2px;
                            height: 0px;
                            transition-duration: 0s;
                            .line-dot-view {
                                animation-duration: 3s;
                                background-position: center 100%;
                            }
                        }
                    }
                }
                &.dispatch-immediately {
                    overflow: hidden;
                    .sr-person-dm-wrap {
                        opacity: 0;
                        visibility: hidden;
                        top: 130.92px;
                        left: 279.5px;
                        width: 96px;
                        height: 184px;
                    }
                    .icon-ex-mark-speech-bubble {
                        opacity: 0;
                        visibility: hidden;
                    }
                    .img-dispatch-vehicle {
                        opacity: 0;
                        visibility: hidden;
                        top: 159.67px;
                        left: 500px;
                        .di-car-siren-machine {
                            top: 18.07px;
                            left: 172.56px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-siren-light {
                            top: 0px;
                            left: 109.54px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-body {
                            top: 33.27px;
                            left: 0.45px;
                            animation-timing-function: linear;
                            animation-duration: 2s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-exhaust {
                            .di-car-exhaust-bar {
                                left: -100%;
                                animation-timing-function: linear;
                                animation-duration: 1s;
                                animation-direction: normal;
                                animation-iteration-count: infinite;
                            }
                            &.di-car-exhaust1 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0s;
                                }
                            }
                            &.di-car-exhaust2 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0.1s;
                                }
                            }
                        }
                    }
                }
            }

            // .popup-layer-animation-wrap에 active시 동작하나 이것을 페이지 step을 타고 걸어주면 된다.
            &.active {
                opacity: 1;
                visibility: unset;
                pointer-events: unset;
                transition-duration: 0.5s;
                .bottom-text-wrap {
                    bottom: 60px;
                    opacity: 1;
                    visibility: unset;
                    transition-delay: 0.5s;
                }
                .animation-box-wrap {
                    // 에스원 관제센터 active
                    &.control-center {
                        .icon-postion-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 0.3s;
                            &.bottom-left {
                                transition-delay: 1s;
                            }
                            &.bottom-right {
                                transition-delay: 1s;
                            }
                            &.bottom-left-top {
                                transition-delay: 1s;
                            }
                            &.bottom-right-top {
                                transition-delay: 1s;
                            }
                            &.bottom-center {
                                transition-delay: 1.5s;
                            }
                            &.top-center {
                                transition-delay: 2s;
                            }
                        }

                        .ellipse-wave-length-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 1s;
                            &.ellipse-wave-length-wrap1 {
                                transition-delay: 2.5s;
                            }
                            &.ellipse-wave-length-wrap2 {
                                transition-delay: 2.5s;
                            }
                            .ellipse-wave-item {
                                transform: translate(-50%, -50%) scale(0);
                                animation-delay: 3s;
                                animation-name: ellipseWaveItem1;
                            }
                        }

                        .line-dot-red {
                            &.center-width {
                                width: 213px;
                                height: 2px;
                                transition-delay: 3s;
                                transition-duration: 1s;
                                &.center-width-left {
                                    .line-dot-view {
                                        animation-name: centerWidthLeft;
                                    }
                                }
                                &.center-width-right {
                                    .line-dot-view {
                                        animation-name: centerWidthRight;
                                    }
                                }
                            }
                            &.center-bottom-top {
                                width: 2px;
                                height: 98px;
                                transition-delay: 3.5s;
                                transition-duration: 1s;
                                .line-dot-view {
                                    animation-name: centerBottomTop;
                                }
                            }
                        }
                    }

                    // 즉시 현장으로 출동 active
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            opacity: 1;
                            visibility: unset;
                            left: 179.5px;
                            transition-delay: 3s;
                            transition-duration: 1s;
                        }
                        .icon-ex-mark-speech-bubble {
                            opacity: 1;
                            visibility: unset;
                            transition-delay: 2s;
                            transition-duration: 1s;
                        }
                        .img-dispatch-vehicle {
                            opacity: 1;
                            visibility: unset;
                            left: 287.53px;
                            transition-delay: 4s;
                            transition-duration: 0.5s;
                            .di-car-siren-light {
                                animation-name: diCarSirenLight;
                            }
                            .di-car-exhaust {
                                .di-car-exhaust-bar {
                                    animation-name: diCarExhaust;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    .ani-icon-secom {
        display: inline-block;
        background-repeat: no-repeat;
        background-position: center center;
        background-size: contain;
        // 링크
        &-link {
            width: 103px;
            height: 68px;
            background-image: url('../../images/ko/showroom/sr5/img-pro-center-pop.svg');
        }
        // 열선 감지기
        &-heat-detector {
            width: 58px;
            height: 120px;
