// [블루스캔(비상주 건물관리)] : /showroom/bluescan.html

// 첫 진입 시 효과

.sr8-bluescan {
    // [블루스캔(비상주 건물관리)] .sr8-bluescan Start
    background-color: rgba(226, 226, 226, 1);
    &.screen1,
    &.screen6 {
        transition-duration: 1s;
        background-color: rgba(206, 206, 206, 1);
    }
    // 진입 효과
    &.default {
        .showroom-background {
            &-layer {
                transform: scale(1.05);
                filter: blur(10px);
                @include elHide();
            }
        }
        .bs-building-layer {
            @include elHide();
            .sr-toast-msg {
                &:before {
                    backdrop-filter: blur(2px);
                }
            }
        }
    }
    &.main {
        .showroom-background {
            &-layer {
                @include elShow();
                transition-duration: 1.3s;
            }
        }
        .bs-building-layer {
            transition-delay: 0.5s;
            transition-duration: 1.2s;
            .sr-toast-msg {
                transition-delay: 0.5s;
            }
        }
        .bs-main-text {
            transition-delay: 0.5s;
            transition-duration: 1.2s;
        }
    }

    // [블루스캔(비상주 건물관리)] 컨텐츠 showroom-content-wrap8
    .showroom-content-wrap8 {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;

        .showroom-screen-wrap {
            @include elHide();
            transition-duration: 0.3s;
            &.active {
                @include elShow();
                .showroom-step-inner {
                    @include elShow();
                }
            }
        }

        .showroom-step-wrap {
            position: absolute;
            top: 0;
            left: 0;
            width: inherit;
            height: inherit;
            .showroom-step-inner {
                position: relative;
                width: 100%;
                height: 100%;
                @include elHide();
                transition-duration: 0.8s;
                // transition-delay: 0.2s;
            }
        }
    }

    .showroom-background {
        // 이미지
        &-area {
            position: absolute;
            width: 1920px;
            height: 1080px;
            top: 50%;
            left: 50%;
        }
        &-inner {
            position: relative;
            width: inherit;
            height: inherit;
        }
        // 배경 인테리어
        &-layer {
            position: absolute;
            top: 145px;
            left: 200px;
            width: 1959px;
            height: 1102px;
            background-image: url('../../images/ko/showroom/sr8/bg-sr8-interior0-1.jpg');
        }
        // 딤 : 배경 어둠/밝기
        &-dim {
            background-image: url('../../images/ko/showroom/sr8/bg-sr8-dimm1-1.png');
            @include elHide();
        }
    }

    .bottom-gray-tooltip-wrap {
        // bottom: -10%;
        transition: 0.3s;
        bottom: 80px;
        background-color: rgba(0, 0, 0, 0);
        padding: 0;
        @include elHide();
        .bottom-gray-text {
            padding: 24px 32px;
            transition: 0.5s;
            .sub-text {
                margin-top: 6px;
                display: block;
                color: $white;
                font-size: 16px;
                font-weight: 400;
            }
        }
        &.active {
            background-color: rgba(36, 36, 36, 0.7);
            @include elShow();
            // bottom: 80px;
        }
    }

    // 메인 사용
    .bs-building {
        &-layer {
            @include sizeSet(549px, 806px);
            @include absolute(top 13.3% left 200px bottom 13.3%);
            @include elHide();
            &:has(.floor-rf a:hover) {
                background: url(../../images/ko/showroom/sr8/bg-sr8-building-hover-whole.png) no-repeat 0 0 / 100%;
            }
            &:has(.bs-building-item a:hover) {
                .floating {
                    opacity: 0;
                }
            }
            > ul {
                @include sizeSet(100%, 100%);
                position: relative;
            }
        }
        &-item {
            position: absolute;
            width: 100%;
            // 지하
            &.under-1 {
                height: 225px;
                bottom: 1px;
                a {
                    .bg {
                        > i {
                            height: 71% !important;
                        }
                    }
                }
                .floating {
                    top: 37%;
                    .icon {
                        > span {
                            background-image: url(../../images/ko/showroom/sr8/icon-sr8-b1.png);
                        }
                    }
                }
            }
            // 1층
            &.floor-1 {
                height: 119px;
                bottom: 226px;
                .floating {
                    .icon {
                        > span {
                            background-image: url(../../images/ko/showroom/sr8/icon-sr8-1f.png);
                        }
                    }
                }
            }
            // 2층
            &.floor-2 {
                height: 121px;
                bottom: 344px;
                .floating {
                    .icon {
                        > span {
                            background-image: url(../../images/ko/showroom/sr8/icon-sr8-2f.png);
                        }
                    }
                }
            }
            // 3층
            &.floor-3 {
                height: 120px;
                bottom: 464px;
                .floating {
                    .icon {
                        > span {
                            background-image: url(../../images/ko/showroom/sr8/icon-sr8-3f.png);
                        }
                    }
                }
            }
            // 4층
            &.floor-4 {
                height: 115px;
                bottom: 583px;
                .floating {
                    .icon {
                        > span {
                            background-image: url(../../images/ko/showroom/sr8/icon-sr8-4f.png);
                        }
                    }
                }
            }
            // 옥상
            &.floor-rf {
                height: 109px;
                top: 0;
                .bg {
                    > i {
                        display: none;
                    }
                }
                .floating {
                    right: 190px;
                    top: 48%;
                    .icon {
                        > span {
                            background-image: url(../../images/ko/showroom/sr8/icon-sr8-rooftop.png);
                        }
                    }
                    .dot {
                        width: 314px;
                    }
                    p {
                        left: 404px;
                    }
                }
            }
            a {
                display: inline-block;
                height: 100%;
                width: calc(100% - 25px);
                @include relative(left 12px);
                &:hover {
                    .floating {
                        opacity: 1 !important;
                        .dot {
                            background-image: url(../../images/ko/showroom/sr8/img-sr8-line-blue.png);
                        }
                        p {
                            font-weight: 700;
                            color: $primary;
                            &:before {
                                @include sizeSet(8px, 8px);
                                background: $primary;
                            }
                        }
                    }
                }
                .bg {
                    display: inline-block;
                    vertical-align: top;
                    width: 100%;
                    height: 100%;
                    font-size: 0;
                    position: relative;
                    &:has(i:hover) {
                        > i {
                            &:before {
                                opacity: 1;
                            }
                        }
                    }
                    > i {
                        display: inline-block;
                        position: absolute;
                        height: 100%;
                        &:before {
                            @include pseudo;
                            @include sizeSet(100%, 100%);
                            position: absolute;
                            border-style: solid;
                            border-color: #78dfff;
                            transition-duration: 0.2s;
                            z-index: 1;
                            opacity: 0;
                        }
                        &:first-of-type {
                            left: 0;
                            top: 0;
                            transform: skewY(12deg);
                            transform-origin: left;
                            width: calc(100% - 220px);
                            &:before {
                                background: linear-gradient(
                                    90deg,
                                    rgba(120, 223, 255, 0.4) 0%,
                                    rgba(0, 0, 0, 0.05) 100%
                                );
                                border-width: 3px 0 3px 3px;
                            }
                        }
                        &:nth-of-type(2) {
                            right: 0;
                            top: -3px;
                            transform: skewY(-17deg);
                            transform-origin: right;
                            width: 220px;
                            &:before {
                                background: linear-gradient(
                                    265.4deg,
                                    rgba(165, 229, 243, 0) 0%,
                                    rgba(196, 238, 247, 0.4) 110.08%
                                );

                                border-width: 3px 3px 3px 0;
                            }
                        }
                    }
                }
                .floating {
                    position: absolute;
                    top: 54%;
                    margin-top: -36px;
                    right: -20px;
                    @include flex(center, null);
                    transition-duration: 0.2s;
                    .icon {
                        display: inline-block;
                        @include sizeSet(72px, 72px);
                        z-index: 3;
                        filter: drop-shadow(0px 0px 4px #00000010);
                        &:before {
                            @include pseudo;
                            @include sizeSet(84px, 84px);
                            top: 50%;
                            left: 50%;
                            margin: -42px 0 0 -42px;
                            background: rgba(217, 217, 217, 0.1);
                            border: 1px solid $white;
                            border-radius: 50%;
                            animation: bsmainIcon 1.5s ease-out infinite;
                            opacity: 0;
                        }
                        > span {
                            display: inline-block;
                            background: $white;
                            border-radius: 50%;
                            overflow: hidden;
                            @include sizeSet(inherit, inherit);
                            background-position: 50%;
                            background-repeat: no-repeat;
                            background-size: 100px 100px;
                        }
                    }
                    .dot {
                        @include sizeSet(104px, 4px);
                        background: url(../../images/ko/showroom/sr8/img-sr8-line-blk.png) repeat-x 0 0 / auto 4px;
                        @include absolute(left 72px);
                    }
                    p {
                        @include absolute(left 192px);
                        white-space: nowrap;
                        font-size: 22px;
                        font-weight: 500;
                        color: #000;
                        &:before {
                            @include pseudo;
                            @include sizeSet(5px, 5px);
                            border-radius: 50%;
                            background: $black;
                            left: -20px;
                            top: 50%;
                            transform: translateY(-50%);
                        }
                    }
                }
            }
        }
    }

    .bs-main-text {
        color: $black;
        line-height: 1;
        @include absolute(top 50%);
        transform: translateY(-50%);
        left: 1185px;
        @include elHide();
        // transition-duration: 1.2s;
        // transition-delay: 0.5s;
        .sub-tit {
            color: #000;
            font-size: 24px;
            font-weight: 500;
        }
        > h2 {
            font-size: 56px;
            font-weight: 700;
            margin-top: 10px;
            color: #000;
        }
        .text {
            color: #353535;
            font-size: 22px;
            font-weight: 400;
            line-height: 1.3;
            margin-top: 25px;
        }
        > button {
            font-size: 20px;
            font-weight: 500;
            color: $white;
            background: $primary;
            height: 50px;
            padding: 0 49.5px;
            line-height: 1;
            border-radius: 4px;
            margin-top: 30px;
        }
    }

    .service-step-wrap {
        @include elHide();
        filter: blur(10px);
        transition-duration: 0.3s;
    }

    /* 스크린 사용 요소 */
    // 포인터
    .sr-pointer {
        @include elHide();
        &.show {
            transition-property: opacity, visibility;
            transition-duration: 0.2s;
            @include elShow();
        }
    }

    // alert 메시지
    .sr-alert-msg {
        display: inline-block;
        @include elHide();
        &.active {
            @include elShow();
            transition-property: opacity;
            transition-duration: 0.3s;
        }
    }

    // 클로즈업 이미지
    .closeup {
        display: inline-block;
        @include elHide();
        &.active {
            transition-duration: 0.3s;
            transition-property: opacity;
            @include elShow();
        }
    }

    // 모바일 이미지 레이어
    .layer-mobile {
        @include sizeSet(460px, 356px);
        @include elHide();
        &.active {
            transition-duration: 0.3s;
            z-index: 5;
            @include elShow();
        }
    }

    // 애니메이션 팝업
    // 양쪽 아이템 하단 - 양쪽 센서랑 cctv - 가운데 세콤
    // - 가로 라인 - 상단 사람 - 세로 라인 순서로 노출
    .popup-sensor {
        display: none;
        // display: block; //테스트 시 사용
        .sr-popup-frame {
            padding-top: 30px;
            &.active {
                span:not(.cctv, .sensor, .line, .line > span),
                strong {
                    animation: bsVisibleAnimate 0.3s ease-in forwards;
                }
                .frame {
                    &-top,
                    &-bottom {
                        .line {
                            > span {
                                &:before {
                                    animation-timing-function: ease-in, linear;
                                    animation-direction: normal;
                                    animation-iteration-count: 1, infinite;
                                    animation-duration: 0.3s, 4s;
                                    animation-fill-mode: forwards, none;
                                    animation-delay: 2s;
                                }
                            }
                        }
                    }
                    &-top {
                        .line {
                            > span {
                                &:before {
                                    animation-name: bsVisibleAnimate, centerBottomTop;
                                }
                            }
                        }
                        .counselor {
                            animation-delay: 2s;
                        }
                    }
                    &-bottom {
                        .line {
                            > span {
                                &.line-left {
                                    &:before {
                                        animation-name: bsVisibleAnimate, centerWidthLeft;
                                    }
                                }
                                &.line-right {
                                    &:before {
                                        animation-name: bsVisibleAnimate, centerWidthRight;
                                    }
                                }
                            }
                        }
                        .left,
                        .right {
                            .bg {
                                animation-delay: 0.5s;
                                animation-name: bsVisibleAnimate, bsSensorPopBg;
                                animation-duration: 0.3s, 1s;
                                animation-timing-function: ease-in, ease-in-out;
                                animation-fill-mode: forwards;
                                animation-iteration-count: 1, infinite;
                                animation-direction: alternate;
                            }
                            strong {
                                animation-delay: 1s;
                            }
                        }
                        .center {
                            animation-delay: 1.5s;
                        }
                    }
                }
            }
            &.blue {
                .line {
                    > span {
                        &:before {
                            background-image: url(../../images/ko/showroom/srcomm/bg-line-dot-scarlet-blue.png);
                        }
                    }
                }
                .bg {
                    background-image: url(../../images/ko/showroom/sr8/img-sr8-popSensor-item-bg-blue.png) !important;
                }
            }
        }
        .frame {
            &-top,
            &-bottom {
                width: 100%;
                position: relative;
                font-size: 0;
                span {
                    display: inline-block;
                    position: absolute;
                }
                .line {
                    transform: translateX(-50%);
                    left: 50%;
                    > span {
                        @include sizeSet(100%, 100%);
                        display: inline-block;
                        &:before {
                            content: '';
                            display: inline-block;
                            @include sizeSet(100%, 100%);
                            background-repeat: repeat;
                            background-size: 10px 10px;
                            background-image: url(../../images/ko/showroom/srcomm/bg-line-dot-scarlet.png);
                            @include elHide();
                        }
                    }
                }
            }
            &-top {
                height: 156px;
                .counselor {
                    @include sizeSet(110px, 124px);
                    background: url(../../images/ko/showroom/sr8/img-sr8-popSensor-person.png) no-repeat 50% / 110px
                        auto;
                    left: 50%;
                    margin-left: -55px;
                    top: 0;
                    @include elHide();
                }
                .line {
                    @include sizeSet(2px, 110px);
                    top: 116px;
                    span {
                        &:before {
                            background-position: 50% 100%;
                        }
                    }
                }
            }
            &-bottom {
                height: 112px;
                .line {
                    @include sizeSet(100%, 2px);
                    bottom: 32px;
                    > span {
                        position: absolute;
                        display: inline-block;
                        @include sizeSet(213px, 2px);
                        &:before {
                            background-position: 0% 50%;
                        }
                    }
                    &-left {
                        left: 84px;
                    }
                    &-right {
                        right: 84px;
                    }
                }
                .item {
                    &.left,
                    &.right {
                        @include sizeSet(169px, 112px);
                        .bg {
                            // 센서, cctv 배경
                            @include sizeSet(169px, 62px);
                            background: url(../../images/ko/showroom/sr8/img-sr8-popSensor-item-bg.png) no-repeat 50%
                                bottom / 169px 62px;
                            @include absolute(bottom 0 left 0 right 0);
                            @include elHide();
                        }
                        strong {
                            // 센서, cctv
                            display: inline-block;
                            @include absolute(left 50% bottom 31px);
                            transform: translateX(-50%);
                            background-position: 50%;
                            background-repeat: no-repeat;
                            @include elHide();
                        }
                    }
                    &.left {
                        left: 0;
                        strong {
                            background-image: url(../../images/ko/showroom/sr8/img-sr8-popSensor-sensor.png);
                            background-size: 59px 80px;
                            @include sizeSet(59px, 80px);
                        }
                    }
                    &.right {
                        right: 0;
                        strong {
                            background-image: url(../../images/ko/showroom/sr8/img-sr8-popSensor-cctv.png);
                            background-size: 70px 50px;
                            @include sizeSet(70px, 50px);
                        }
                    }
                    &.center {
                        @include sizeSet(88px, 40px);
                        background: url(../../images/ko/showroom/sr8/img-sr8-popSensor-secom.png) no-repeat 50% / 88px
                            40px;
                        left: 50%;
                        bottom: 12.5px;
                        margin-left: -44px;
                        @include elHide();
                    }
                }
            }
        }
    }

    // 각 층 끝날 때 띄우는 팝업
    .popup-monitor {
        .sr-popup-frame {
            background: url(../../images/ko/showroom/sr8/img-sr8-st4-popup.png) no-repeat 50% / 446px 306px;
        }
    }

    .sr-round-beam {
        @include absolute(left 50% top 50%);
        margin: -68.5px 0 0 -68.5px;
        @include sizeSet(137px, 137px);
        z-index: -1;
        @include elHide();
        transition-duration: 0.3s;
        &.active {
            @include elShow();
            // [class^='sr-round-beam-layer'] {
            //     animation-play-state: running;
            // }
        }
        [class^='sr-round-beam-layer'] {
            background: $primary;
            background: radial-gradient(
                circle,
                rgba(0, 0, 0, 0) 0%,
                rgba(19, 70, 153, 0.2) 40%,
                rgba(29, 108, 235, 0.9) 100%
            );
            @include absolute(left 50% top 50%);
            border-radius: 50%;
            animation-iteration-count: infinite;
            animation-timing-function: ease-out;
            animation-duration: 1s;
            animation-delay: 0.3s;
            // animation-play-state: paused;
            @include absolute(left 50% top 50%);
        }
        &-layer {
            &-1 {
                animation-name: srPointerLayer1;
                margin: -37.5px 0 0 -37.5px;
                @include sizeSet(75px, 75px);
            }
            &-2 {
                animation-name: srPointerLayer2;
                margin: -68.5px 0 0 -68.5px;
                @include sizeSet(137px, 137px);
            }
        }
    }

    &.default {
        // 배경 : 인테리어, 딤 기본설정
        .showroom-background {
            // 이미지
            &-area {
                position: absolute;
                width: 1920px;
                height: 1080px;
                top: 50%;
                left: 50%;
            }
            &-inner {
                position: relative;
                width: inherit;
                height: inherit;
            }
            // 배경 인테리어
            &-layer {
                position: absolute;
                @include bgCenterSet;
                top: 145px;
                left: 200px;
                width: 1082px;
                height: 814px;
                background-image: url('../../images/ko/showroom/sr8/bg-sr8-interior0-1.jpg');
            }
            // 딤 : 배경 어둠/밝기
            &-dim {
                background-image: url('../../images/ko/showroom/sr8/bg-sr8-dimm1-1.png');
                @include elHide();
            }
        }
        .showroom-step-wrap {
            @include elHide();
            filter: blur(20px);
        }
    }

    // 카테고리의 메인
    &.main {
        .showroom-background {
            // 배경 인테리어
            &-layer {
                @include bgCenterSet;
                top: 145px;
                left: 200px;
                width: 1082px;
                height: 814px;
                background-image: url('../../images/ko/showroom/sr8/bg-sr8-interior0-1.jpg');
                transform: scale(1);
                opacity: 1;
                // filter: unset;
                // visibility: unset;
                // transition-delay: 0s;
                // transition-duration: 1s;
            }
            // 딤 : 배경 어둠/밝기
            &-dim {
                background-image: url('../../images/ko/showroom/sr8/bg-sr8-dimm1-1.png');
                @include elHide();
                transition-delay: 0s;
                transition-duration: 0s;
            }
        }
        .showroom-step-wrap {
            filter: unset;
            @include elShow();
        }
        .showroom-screen0-wrap {
            @include elShow();
            &.active {
                .bs-building-layer {
                    @include elShow();
                }
            }
            .bs-main-text {
                @include elShow();
            }
        }
    }
    &[class*='screen'] {
        .service-step-wrap {
            @include elShow();
            filter: unset;
        }
    }
    // 화면1 : B1 누수감시
    &.screen1 {
        .bs-cctv {
            opacity: 0;
            &-wrap {
                @include absolute(top 93px left 506px);
                font-size: 0;
                z-index: 10;
            }
            &-item {
                @include sizeSet(46px, 33px);
                background: url(../../images/ko/showroom/sr8/img-sr8-cctv-item.png) no-repeat 50% / 100% auto;
                display: inline-block;
            }
        }
        .closeup-1 {
            display: none;
        }
        .layer-mobile {
            @include absolute(top 362px left 251px);
        }
        .sr-lk-sensor {
            @include elHide();
            transition-property: opacity, visibility;
            &.active {
                transition-duration: 0.3s;
                @include elShow();
            }
        }
        &.step1 {
            .showroom-background {
                // 배경 인테리어
                &-layer {
                    @include bgCenterSet;
                    top: 32.04px;
                    left: -94.93px;
                    width: 1703px;
                    height: 1055px;
                    background-image: url('../../images/ko/showroom/sr8/bg-sr8-interior1-1.jpg');
                    transform: scale(1);
                    @include elShow();
                    transition-delay: 0s;
                    transition-duration: 1s;
                }
                // 딤 : 배경 어둠/밝기
                &-dim {
                    background-image: url('../../images/ko/showroom/sr8/bg-sr8-dimm1-1.png');
                    @include elShow();
                    transition-delay: 0s;
                    transition-duration: 1s;
                }
            }
            .sr-pointer {
                position: absolute;
