.wrap-online-showroom {
  letter-spacing: -0.3px;
}
.wrap-online-showroom .sr-pointer {
  position: relative;
  width: 88px;
  height: 88px;
}
.wrap-online-showroom .sr-pointer.active .sr-pointer-pin {
  transition-duration: 0.3s;
}
.wrap-online-showroom .sr-pointer.active:hover .sr-pointer-pin {
  width: 24px;
  height: 24px;
}
.wrap-online-showroom .sr-pointer.active .sr-pointer-layer-1 {
  animation-name: srPointerLayer1;
}
.wrap-online-showroom .sr-pointer.active .sr-pointer-layer-2 {
  animation-name: srPointerLayer2;
}
.wrap-online-showroom .sr-pointer.red .sr-pointer-pin {
  background: #ff4554;
}
.wrap-online-showroom .sr-pointer.red .sr-pointer-layer [class*=sr-pointer-layer-] {
  background: #ff4554;
  background: radial-gradient(circle, rgba(255, 69, 84, 0) 0%, rgba(255, 69, 84, 0.4) 100%);
}
.wrap-online-showroom .sr-pointer.blue.active .sr-pointer-layer-1 {
  animation-name: srPointerLayer1;
}
.wrap-online-showroom .sr-pointer.blue.active .sr-pointer-layer-2 {
  animation-name: srPointerLayer2;
}
.wrap-online-showroom .sr-pointer.blue .sr-pointer-pin {
  background: #1d6ceb;
}
.wrap-online-showroom .sr-pointer.blue .sr-pointer-layer [class*=sr-pointer-layer-] {
  background: #1d6ceb;
  background: radial-gradient(circle, rgba(29, 108, 235, 0) 0%, rgba(29, 108, 235, 0.3) 100%);
}
.wrap-online-showroom .sr-pointer-pin {
  top: 50%;
  left: 50%;
  position: absolute;
  transform: translate(-50%, -50%);
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid #fff;
  z-index: 3;
  transition: 0.2s ease-out;
}
.wrap-online-showroom .sr-pointer-layer [class*=sr-pointer-layer-] {
  top: 50%;
  left: 50%;
  position: absolute;
  border-radius: 50%;
  animation-iteration-count: infinite;
  animation-timing-function: ease-out;
  animation-duration: 1s;
}
.wrap-online-showroom .sr-pointer-layer-1 {
  width: 48px;
  height: 48px;
  margin: -24px 0 0 -24px;
  transform: scale(0);
}
.wrap-online-showroom .sr-pointer-layer-2 {
  width: 72px;
  height: 72px;
  margin: -36px 0 0 -36px;
  transform: scale(0);
}
.wrap-online-showroom .sr-targeting {
  display: inline-block;
  width: 144px;
  height: 144px;
  position: relative;
}
.wrap-online-showroom .sr-targeting.active .sr-targeting-frame {
  animation-duration: 1s;
  animation-iteration-count: 1;
  animation-timing-function: steps(2, end);
  animation-name: srTargetingFrame;
}
.wrap-online-showroom .sr-targeting.active .sr-targeting-inner {
  animation-duration: 0.7s;
  animation-delay: 1s;
  animation-iteration-count: infinite;
  animation-name: srTargetingInner;
}
.wrap-online-showroom .sr-targeting .sr-targeting-frame {
  display: inline-block;
  width: 118px;
  height: 118px;
  top: 50%;
  left: 50%;
  position: absolute;
  transform: translate(-50%, -50%);
  background-repeat: no-repeat;
  background-position: 50% 50%;
  background-size: 118px 118px;
  background-image: url(../../images/ko/showroom/srcomm/sr-targeting-frame.png);
}
.wrap-online-showroom .sr-targeting .sr-targeting-inner {
  display: inline-block;
  width: 100px;
  height: 100px;
  top: 50%;
  left: 50%;
