  display: block;
  width: 290px;
}
.wrap-online-showroom [data-tooltip-wrap] [data-tooltip] [data-tooltip-text] {
  display: none;
}
.wrap-online-showroom [data-tooltip-wrap][data-tooltip-bottom] [data-tooltip] {
  top: unset;
  bottom: 20px;
}
.wrap-online-showroom [data-tooltip-wrap][data-tooltip-bottom] .sr-float-tooltip:before {
  content: "";
  display: block;
  position: absolute;
  border-bottom: 7px solid rgba(36, 83, 204, 0.9);
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  top: unset;
  bottom: -10px;
  left: 50%;
  transform: translateX(-50%) scaleY(-1);
}
.wrap-online-showroom .sr-float-tooltip {
  background: rgba(36, 83, 204, 0.9);
  border-radius: 4px;
  width: max-content;
  z-index: 5;
  box-shadow: 0px 10px 15px 0px rgba(0, 0, 0, 0.15);
}
.wrap-online-showroom .sr-float-tooltip.show {
  width: 290px;
}
