  transform: rotate(45deg);
}
.wrap-online-showroom .sr-float-tooltip.show [data-tooltip-title] p:after {
  display: none;
}
.wrap-online-showroom .sr-float-tooltip:before {
  content: "";
  display: block;
  position: absolute;
  border-bottom: 7px solid rgba(36, 83, 204, 0.9);
  border-left: 6px solid transparent;
  border-right: 6px solid transparent;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
}
.wrap-online-showroom .sr-float-tooltip [data-tooltip-title] {
