.wrap-online-showroom .sr-float-tooltip [data-tooltip-title]:after {
  width: 18px;
  height: 18px;
  content: "";
  display: block;
  position: absolute;
  right: 8px;
  top: 50%;
  margin-top: -9px;
  background: url(../../images/ko/showroom/srcomm/icon-plus-white.png) no-repeat 50%/18px 18px;
}
.wrap-online-showroom .sr-float-tooltip [data-tooltip-text] {
  padding: 8px 14px 18px;
}
.wrap-online-showroom .sr-float-tooltip [data-tooltip-text] > p {
