  padding: 24px 32px;
  line-height: 1;
  display: inline-block;
  top: 50%;
  left: 50%;
  position: absolute;
  transform: translate(-50%, -50%);
  z-index: 50;
  width: max-content;
  transition: 1s;
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.wrap-online-showroom .sr-toast-msg.active {
  opacity: 1;
  visibility: unset;
  pointer-events: unset;
}
