}
.wrap-online-showroom .sr-toast-msg:before {
  content: "";
  display: inline-block;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  position: absolute;
  backdrop-filter: blur(2px);
  background: rgba(36, 36, 36, 0.8);
  z-index: -1;
