  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.wrap-online-showroom .sr-alert-msg.active {
  opacity: 1;
  visibility: unset;
  pointer-events: unset;
}
.wrap-online-showroom .sr-alert-msg:has(.complete) > p {
  background: #1fb279;
