.wrap-online-showroom .sr-alert-msg > p {
  padding: 10px 18px;
  line-height: 24px;
  border-radius: 50px;
  font-size: 18px;
  font-weight: 600;
  color: #fff;
}
.wrap-online-showroom .sr-alert-msg i {
  display: inline-block;
  vertical-align: top;
  width: 24px;
  height: 24px;
  margin-right: 2px;
