.wrap-online-showroom {
    &.header-gnb-view {
        .header_wrap {
            top: 0px;
            opacity: 1;
            visibility: unset;
            transition-duration: 0.6s;
        }
    }
    .header-hover-view {
        display: block;
        z-index: 10;
        position: fixed;
        height: 20px;
        top: 0px;
        left: calc(5% + 100px);
        right: 0px;
    }
    .header_wrap {
        top: -120px;
        opacity: 0;
        visibility: hidden;
    }
}

// 인트로 : /showroom/intro.html
.wrap-online-showroom {
    // 스와이퍼 썸네일 이미지 버튼 눌렀을 경우 안보이게
    .iframe-video.active + .thumbnail-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    &.wrap-online-showroom-intro {
        background-color: rgba(226, 226, 226, 1);
    }
    .showroom-container-wrap {
        &.sr0-prograss {
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
            z-index: 20;
            &.active {
                opacity: 1;
                visibility: unset;
                pointer-events: unset;
            }
            &.prev {
                z-index: 0;
                opacity: 0;
                visibility: hidden;
                pointer-events: none;
                .title-prograss-wrap {
                    transition-duration: 0s;
                }
                .bg-prograss-wrap {
                    .bg-prograss-inner {
                        .bg-prograss-top,
                        .bg-prograss-bottom {
                            transition-duration: 0s;
                        }
                    }
                }
            }
            .prograsbar-wrap {
                position: absolute;
                top: 50%;
                left: 0;
                transform: translateY(-50%);
                width: 100%;
                height: 1px;
                background-color: rgba(255, 255, 255, 0.1);
                z-index: 1;
                opacity: 0;
                visibility: hidden;
                &.active {
                    opacity: 1;
                    visibility: unset;
                }
                .prograsbar-inner {
                    position: relative;
                    width: inherit;
                    height: inherit;
                    .prograsbar-line {
                        position: absolute;
                        top: 0;
                        left: 0;
                        height: inherit;
                        background-color: rgba(255, 255, 255, 1);
                        opacity: 1;
                        visibility: unset;
                    }
                }
            }
            .title-prograss-wrap {
                position: absolute;
                top: calc(50% - 85px);
                left: 50%;
                transform: translate(-50%, -50%);
                opacity: 0;
                visibility: unset;
                z-index: 1;
                transition-duration: 0.5s;
            }
            .bg-prograss-wrap {
                position: absolute;
                width: 100%;
                height: 100%;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                &.active {
                    .bg-prograss-inner {
                        .title-prograss-wrap {
                            opacity: 1;
                            visibility: unset;
                        }
                        .bg-prograss-top {
                            height: 50%;
                        }
                        .bg-prograss-bottom {
                            height: 50%;
                        }
                    }
                }
                .bg-prograss-inner {
                    position: relative;
                    width: inherit;
                    height: inherit;
                    .bg-prograss-top {
                        position: absolute;
                        top: 0;
                        left: 0;
                        width: inherit;
                        height: 0%;
                        background-color: rgba(0, 0, 0, 1);
                        transition-duration: 0.5s;
                    }
                    .bg-prograss-bottom {
                        position: absolute;
                        bottom: 0;
                        left: 0;
                        width: inherit;
                        height: 0%;
                        background-color: rgba(0, 0, 0, 1);
                        transition-duration: 0.5s;
                    }
                }
            }
        }

        &.sr0-intro {
            &.active {
                opacity: 1;
                visibility: unset;
            }
            background-repeat: no-repeat;
            background-position: center center;
            background-size: cover;
            background-color: rgba(202, 203, 205, 1); // #cacbcd
            background-image: url('../../images/ko/showroom/sr0/bg-online-showroom.jpg');
            opacity: 0;
            visibility: hidden;
            .title-intro-n-wrap {
                position: absolute;
                // top: 125px;
                top: 11%;
                left: 50%;
                transform: translateX(-50%);
                z-index: 1;
                .title-intro-n {
                    .text {
                        color: rgba(255, 255, 255, 1);
                    }
                }
                .sub-text-intro-n-wrap {
                    .text {
                        color: rgba(255, 255, 255, 1);
                    }
                }
                .text-bold {
                    font-weight: 700;
                }
            }
            .showroom-content-wrap {
                &.showroom-intro {
                    width: 1920px;
                    height: 1080px;
                    top: 50%;
                    left: 50%;
                    .intro-service-box-wrap {
                        transition: 0.4s padding-top;
                        &.action {
                            .intro-service-box-item-wrap {
                                &.intro-service-box-item-wrap1 {
                                    transform: perspective(150px) rotateY(4deg) scale(0.9);
                                    transition-duration: 3s;
                                    opacity: 1;
                                    visibility: unset;
                                }
                                &.intro-service-box-item-wrap2 {
                                    transform: perspective(75px) rotateY(-2deg) scale(0.9);
                                    transition-duration: 3s;
                                    opacity: 1;
                                    visibility: unset;
                                }
                            }
                        }
                        &.open {
                            .intro-service-box-item-wrap {
                                &:hover {
                                    &.intro-service-box-item-wrap1 {
                                        left: -4px;
                                        transform: perspective(1200px) rotateY(0deg) scale(1);
                                        .isbi-content-wrap {
                                            transform: scale(1);
                                        }
                                    }
                                    &.intro-service-box-item-wrap2 {
                                        right: -4px;
                                        transform: perspective(1200px) rotateY(0deg) scale(1);
                                        .isbi-content-wrap {
                                            transform: scale(1);
                                        }
                                    }
                                    &.intro-service-box-item-wrap {
                                        // cursor: pointer;
                                        .intro-service-box-item-inner {
                                            .isbi-content-wrap {
                                                .isbi-content-inner {
                                                    .isbi-content-list {
                                                        left: 0;
                                                        opacity: 1;
                                                        visibility: unset;
                                                    }
                                                    .bg-service-box-dim {
                                                        background-color: rgba(0, 0, 0, 0.1);
                                                    }
                                                    .bg-service-box-item {
                                                        filter: blur(50px);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                &.active {
                                    &.intro-service-box-item-wrap1 {
                                        left: -4px;
                                        transform: perspective(1200px) rotateY(0deg) scale(1);
                                        .isbi-content-wrap {
                                            transform: scale(1);
                                        }
                                    }
                                    &.intro-service-box-item-wrap2 {
                                        right: -4px;
                                        transform: perspective(1200px) rotateY(0deg) scale(1);
                                        .isbi-content-wrap {
                                            transform: scale(1);
                                        }
                                    }
                                    &.intro-service-box-item-wrap {
                                        .intro-service-box-item-inner {
                                            .isbi-content-wrap {
                                                .isbi-content-inner {
                                                    .isbi-content-list {
                                                        left: 0;
                                                        opacity: 1;
                                                        visibility: unset;
                                                    }
                                                    .bg-service-box-dim {
                                                        background-color: rgba(0, 0, 0, 0.2);
                                                    }
                                                    .bg-service-box-item {
                                                        filter: blur(50px);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                &.intro-service-box-item-wrap1 {
                                    transition-duration: 0.3s;
                                }
                                &.intro-service-box-item-wrap2 {
                                    transition-duration: 0.3s;
                                }
                            }
                        }
                        &.active {
                        }
                    }
                    .intro-service-box-item-wrap {
                        position: absolute;
                        &.intro-service-box-item-wrap1 {
                            top: 0px;
                            left: 55px;
                            transform: perspective(150px) rotateY(4deg) scale(0.8);
                            opacity: 0;
                            visibility: hidden;
                            transition-duration: 0.3s;
                            .isbi-content-wrap {
                                transform: scale(0.95);
                                transition-duration: 0.3s;
                            }
                        }
                        &.intro-service-box-item-wrap2 {
                            top: 0;
                            right: 45px;
                            transform: perspective(50px) rotateY(-2deg) scale(1.1);
                            opacity: 0;
                            visibility: hidden;
                            transition-duration: 0.3s;
                            .isbi-content-wrap {
                                transform: scale(0.95);
                                transition-duration: 0.3s;
                            }
                        }
                    }
                }
            }
            .button-intro-box-vc {
                position: absolute;
                left: 50%;
                // bottom: 60px;
                bottom: 4%;
                transform: translateX(-50%);
            }
        }
    }
