.popup-layer-pm-fm1 {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    &.active {
        opacity: 1;
        visibility: unset;
        pointer-events: unset;
        z-index: 201;
        &::before {
            content: '';
            display: block;
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            background-color: rgba(40, 40, 40, 0.5);
            backdrop-filter: blur(15px);
            opacity: 1;
            visibility: unset;
        }
    }
    &::before {
        content: '';
        display: block;
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        background-color: rgba(40, 40, 40, 1);
        backdrop-filter: blur(0px);
        visibility: hidden;
        pointer-events: none;
    }
    .btn-layer-popup-close {
        position: absolute;
        top: 24px;
        right: 24px;
        width: 58.5px;
        height: 58.5px;
        background-position: center;
        background-repeat: no-repeat;
        background-size: contain;
        background-image: url('../../images/ko/showroom/sr0/btn-layer-popup-close.png');
    }
    .iframe-content-wrap {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 100%;
        max-width: 1280px;
        height: 720px;
        .iframe-content-inner {
            position: relative;
            width: 100%;
            height: 100%;
        }
        .iframe-movie {
            width: 100%;
            height: 100%;
        }
        .thumbnail-wrap {
            background-image: url('../../images/ko/showroom/sr0/s1-thum-intro.jpg');
        }
        .button-movie-start {
            width: 80px;
            height: 80px;
            background-image: url('../../images/ko/showroom/sr0/btn-intro-movie-play.svg');
            background-size: 80px 80px;
            background-color: unset;
        }
        .iframe-video {
            width: 100%;
            height: 100%;
        }
        .iframe-video.active + .thumbnail-wrap {
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
        }
    }
}

// 인트로 세로 해상도에 따라 메뉴 padding-top 변경
@media screen and (max-height: 1080px) {
    .wrap-online-showroom {
        // default
        .intro-service-box-wrap {
            padding-top: 17%;
        }
    }
}
