.wrap-online-showroom {
    //-- Common --//
    // 포인터
    @keyframes srPointerLayer1 {
        0% {
            transform: scale(0);
        }
        80% {
            transform: scale(1);
        }
        100% {
            transform: scale(1);
            opacity: 1;
        }
    }
    @keyframes srPointerLayer2 {
        0% {
            transform: scale(0);
        }
        80% {
            opacity: 0.4;
        }
        100% {
            transform: scale(1.3);
            opacity: 0;
        }
    }
    // 타겟팅
    @keyframes srTargetingFrame {
        0% {
            background-size: 18px 18px;
        }
        100% {
            background-size: 118px 118px;
        }
    }
    @keyframes srTargetingInner {
        0% {
            opacity: 0;
        }
        100% {
            opacity: 1;
        }
    }
    //* sr3_store - Animation ------ Start *//

    //-- Main --//
    // 감지 아이콘(적색) - 출입 이상 감지!, CCTV 확인 필요!, 이상 침입자 감지!
    @keyframes sPointerRed {
        0% {
            background-image: url('../../images/ko/showroom/s-pointer1.png');
        }
        50% {
            background-image: url('../../images/ko/showroom/s-pointer2.png');
        }
        100% {
            background-image: url('../../images/ko/showroom/s-pointer3.png');
        }
    }

    //-- Screen1 - 이상 침입자 감지! --//
    // STEP1 : 푸른 파장 - 자석 감지기 작동

    // STEP1, STEP2 : 도둑 포착

    // STEP2, STEP3 : 열선 감지기 작동

    // STEP3 : 팝업 내 - 이상신호 관제센터 전달

    // STEP4 : 팝업 내 - 출동요원 출동

    //-- Screen2 - CCTV 확인 필요! --//
    // STEP2, STEP3 : 열선 감지기 작동

    //-- Screen3 - 출입 이상 감지! --//
    /// STEP2 : 감지 아이콘(청색)

    //* sr3_store - Animation ------ End *//

    //--------------------------------------------------//

    //* sr8_bluescan - Animation ------ Start *//

    //-- Main --//

    // 아이콘
    @keyframes bsmainIcon {
        0% {
            transform: scale(0.7);
            filter: unset;
        }
        70% {
            opacity: 0.8;
        }
        100% {
            filter: blur(0.3px);
            transform: scale(1);
        }
    }

    // STEP1 :
    // 열선 감지기 작동, 팝업 내 - 이상신호 관제센터 전달 <== sr3_store과 중복
    @keyframes bsVisibleAnimate {
        0% {
            @include elHide();
        }
        100% {
            @include elShow();
        }
    }
    @keyframes bsSensorPopBg {
        0% {
            transform: scale(0.7);
        }
        100% {
            transform: scale(1.1);
        }
    }
    // 애니메이션 팝업 내 관제센터 왕복
    @keyframes bsLineVerAnimate {
        0% {
            bottom: -83px;
            height: 0%;
        }
        100% {
            bottom: -83px;
            height: 100%;
        }
    }
    @keyframes bsLineHorAnimate {
        0% {
            width: 0;
        }
        100% {
            width: 240px;
        }
    }

    // SCREEN2 :
    // cctv, 공기질 센서 진입 시
    @keyframes bsBgBigger {
        0% {
            transform: scale(0);
        }
        100% {
            transform: scale(1);
        }
    }

    //* sr8_bluescan - Animation ------ End *//
}
