// [공동주택] : /showroom/villa.html

.sr2-villa {
    // [공동주택] .sr1-house Start
    background-color: rgba(202, 204, 208, 1);

    // [공동주택] 컨텐츠 showroom-content-wrap2
    .showroom-content-mark {
        border: 0 !important;
    }

    // 우측 스텝 메뉴 초기셋팅
    .service-step-wrap {
        opacity: 0;
        visibility: hidden;
        top: 52%;
        .service-step-inner {
            &::after {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                display: block;
                content: '';
                background-repeat: no-repeat;
                background-position: center center;
                background-size: 100% 100%;
                // background-image: url('../../images/ko/showroom/sr3/bg-sr3-dimm1-3-1.png');
                background-color: rgba(0, 0, 0, 0.75);
                filter: blur(0px);
                transition-delay: 0s;
                transition-duration: 0s;
                opacity: 0;
                visibility: hidden;
                border-radius: 20px;
                pointer-events: none;
            }
        }
    }

    // 스와이퍼 썸네일 이미지
    .swiper-layer-wrap {
        &.swiper-layer-wrap1 {
            .thumbnail-wrap {
                &.thumbnail-wrap1 {
                    background-image: url('../../images/ko/showroom/thumbnail/s1-sr2-villa-sc1.jpg');
                }
                &.thumbnail-wrap2 {
                    background-image: url('../../images/ko/showroom/srcomm/sc-sec-swiper1-2.jpg');
                }
                &.thumbnail-wrap3 {
                    background-image: url('../../images/ko/showroom/srcomm/sc-sec-swiper1-3.jpg');
                }
            }
        }
    }
    // 스와이퍼 썸네일 이미지 버튼 눌렀을 경우 안보이게
    .iframe-video.active + .thumbnail-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }
    // [공동주택] 컨텐츠 showroom-content-wrap2
    .showroom-content-wrap2 {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;
    }

    // 스크린 공통
    .showroom-screen-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    // 스텝 공통
    .showroom-step-wrap {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 100%;
        height: 100%;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    // 스텝 안 공통
    .showroom-step-inner {
        position: relative;
        width: 100%;
        height: 100%;
    }

    // 배경 : 인테리어, 딤 기본설정
    .showroom-background {
        // 이미지
        &-area {
            position: absolute;
            width: 1920px;
            height: 1080px;
            top: 50%;
            left: 50%;
        }
        &-inner {
            position: relative;
            width: inherit;
            height: inherit;
        }
        // 배경 인테리어
        &-layer {
            position: absolute;
            top: 37px;
            left: 0px;
            width: 1940px;
            height: 1090px;
            background-image: url('../../images/ko/showroom/sr2/bg-sr2-interior0-1.jpg');
            transform: scale(1);
            opacity: 0;
            visibility: hidden;
        }
        // 딤 : 배경 어둠/밝기
        &-dim {
            background-image: url('../../images/ko/showroom/sr2/bg-sr2-dimm0-1.png');
            opacity: 0;
            visibility: hidden;
        }
    }

    // 카테고리의 메인
    &.main {
        .showroom-background {
            // 배경 인테리어
            &-layer {
                @include bgCenterSet;
                top: 37px;
                left: 0px;
                width: 1940px;
                height: 1090px;
                background-image: url('../../images/ko/showroom/sr2/bg-sr2-interior0-1.jpg');
                transform: scale(1);
                filter: blur(0px);
                opacity: 1;
                visibility: unset;
                transition-delay: 0s;
                transition-duration: 1s;
            }
            // 딤 : 배경 어둠/밝기
            &-dim {
                background-image: url('../../images/ko/showroom/sr2/bg-sr2-dimm0-1.png');
                opacity: 1;
                visibility: unset;
                transition-delay: 1s;
                transition-duration: 1s;
            }
        }
    }

    // 메인 포인터
    .sr-pointer-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        &.sr-pointer-wrap1 {
            top: 389.69px;
            left: 372.31px;
        }
        &.sr-pointer-wrap2 {
            top: 145.73px;
            left: 866.31px;
        }
        &.sr-pointer-wrap3 {
            top: 535.73px;
            left: 1497.81px;
        }
        &.check-complete {
            transition-delay: 0s !important;
            transition-duration: 0s !important;
            opacity: 0 !important;
            visibility: hidden !important;
            pointer-events: none !important;
        }
    }

    // 안심
    .popup-check-complete-wrap {
