            .icon-complete-check-inner {
                display: inline-block;
                position: relative;
                width: 100%;
                height: 100%;
                box-sizing: border-box;
                border-radius: 50%;
                border: 3px solid rgba(0, 114, 206, 1);
                &::after {
                    position: absolute;
                    top: 50%;
