// Hex to RGBA Converter => https://rgbacolorpicker.com/hex-to-rgba

.header_wrap {
    &.on {
        .gnb_item {
            button {
                &.button_round_blue {
                    &::after {
                        display: none;
                        background: none;
                    }
                }
            }
        }
    }
    .gnb_box {
        .gnb_item {
            button {
                &.button_round_blue {
                    position: relative;
                    color: rgba(255, 255, 255, 1);
                    &::before {
                        display: block;
                        content: '';
                        position: absolute;
                        z-index: -1;
                        top: 50%;
                        left: 50%;
                        width: 100%;
                        height: calc(100% - 29px);
                        transform: translate(-50%, -50%);
                        background-color: rgba(0, 114, 206, 1);
                        border-radius: 25px;
                    }
                }
            }
        }
    }
}

// 공통 컴포넌트 관련 css
.wrap-online-showroom {
    letter-spacing: -0.3px;
    // 포인터
    .sr-pointer {
        // position: absolute;
        position: relative;
        @include sizeSet(88px, 88px);
        &.active {
            .sr-pointer-pin {
                transition-duration: 0.3s;
            }
            &:hover {
                .sr-pointer-pin {
                    @include sizeSet(24px, 24px);
                }
            }
            .sr-pointer-layer-1 {
                animation-name: srPointerLayer1;
            }
            .sr-pointer-layer-2 {
                animation-name: srPointerLayer2;
            }
        }
        &.red {
            .sr-pointer-pin {
                background: $secondary;
            }
            .sr-pointer-layer {
                [class*='sr-pointer-layer-'] {
                    background: $secondary;
                    background: radial-gradient(circle, rgba(255, 69, 84, 0) 0%, rgba(255, 69, 84, 0.4) 100%);
                }
            }
        }
        &.blue {
            &.active {
                .sr-pointer-layer-1 {
                    animation-name: srPointerLayer1;
                }
                .sr-pointer-layer-2 {
                    animation-name: srPointerLayer2;
                }
            }
            .sr-pointer-pin {
                background: $primary;
            }
            .sr-pointer-layer {
                [class*='sr-pointer-layer-'] {
                    background: $primary;
                    background: radial-gradient(circle, rgba(29, 108, 235, 0) 0%, rgba(29, 108, 235, 0.3) 100%);
                }
            }
        }
        &-pin {
            @include absolute(left 50% top 50%);
            transform: translate(-50%, -50%);
            @include sizeSet(16px, 16px);
            border-radius: 50%;
            border: 2px solid $white;
            z-index: 3;
            transition: 0.2s ease-out;
        }
        &-layer {
            [class*='sr-pointer-layer-'] {
                @include absolute(left 50% top 50%);
                border-radius: 50%;
                animation-iteration-count: infinite;
                animation-timing-function: ease-out;
                animation-duration: 1s;
            }
            &-1 {
                @include sizeSet(48px, 48px);
                margin: -24px 0 0 -24px;
                transform: scale(0);
            }
            &-2 {
                @include sizeSet(72px, 72px);
                margin: -36px 0 0 -36px;
                transform: scale(0);
            }
        }
    }

    // 타겟팅
    .sr-targeting {
        display: inline-block;
        @include sizeSet(144px, 144px);
        // position: absolute;
        position: relative;
        &.active {
            .sr-targeting-frame {
                animation-duration: 1s;
                animation-iteration-count: 1;
                // animation-timing-function: ease-in;
                animation-timing-function: steps(2, end);
                animation-name: srTargetingFrame;
            }
            .sr-targeting-inner {
                animation-duration: 0.7s;
                animation-delay: 1s;
                animation-iteration-count: infinite;
                animation-name: srTargetingInner;
            }
        }
        .sr-targeting-frame {
            display: inline-block;
            @include sizeSet(118px, 118px);
            @include absolute(left 50% top 50%);
            transform: translate(-50%, -50%);
            background-repeat: no-repeat;
            background-position: 50% 50%;
            background-size: 118px 118px;
            background-image: url(../../images/ko/showroom/srcomm/sr-targeting-frame.png);
        }
        .sr-targeting-inner {
            display: inline-block;
            @include sizeSet(100px, 100px);
            @include absolute(left 50% top 50%);
            transform: translate(-50%, -50%);
            background-color: rgba(120, 223, 255, 0.15);
            opacity: 0;
        }
    }

    // 말풍선
    .sr-title-sign {
        display: inline-block;
        font-size: 0;
        // position: absolute;
        position: relative;
        &.type-blue {
            &:after {
                border-top: 8px solid rgba(36, 83, 204, 0.9);
            }
            .sign {
                &-box {
                    background-color: rgba(36, 83, 204, 0.9);
                }
                &-text {
                    color: $white;
                }
            }
        }
        &:after {
            margin: 5px auto 0;
            content: '';
            display: block;
            @include sizeSet(0, 0);
            border-top: 8px solid $white;
            border-left: 6px solid transparent;
            border-right: 6px solid transparent;
            transition-duration: 0.3s;
        }
        .sign {
            &-box {
                display: block;
                min-width: 82px;
                text-align: center;
                background-color: rgba(255, 255, 255, 0.9);
                padding: 8px 14px;
                border-radius: 4px;
                box-shadow: 0 12px 12px rgba(0, 0, 0, 0.15);
                transition-duration: 0.3s;
            }
            &-text {
                display: inline-block;
                font-weight: 700;
                font-size: 16px;
                line-height: 21px;
                letter-spacing: -0.3px;
                text-align: center;
                transition-duration: 0.3s;
            }
        }
    }

    .sr-speech-bubble {
        display: inline-block;
        line-height: 1;
        filter: drop-shadow(5px 20px 30px rgba(0, 0, 0, 0.15));
        &-inner {
            position: relative;
            display: inline-block;
            padding-bottom: 16.5px;
            font-size: 0;
        }
        &-text {
            font-size: 24px;
            font-weight: 600;
            color: #000;
            padding: 30px 45px;
            line-height: 1.3;
            position: relative;
            z-index: 1;
            > em {
                font-weight: inherit;
                position: relative;
                &:before {
                    @include pseudo;
                    height: 12px;
                    background: #c8e4ff;
                    z-index: -1;
                    bottom: -1px;
                    left: -3px;
                    right: -3px;
                }
            }
        }
        &-box {
            background: rgba(249, 249, 249, 0.9);
            border-radius: 60px;
            display: inline-block;
            @include absolute(top 0 right 0 bottom 16.5px left 0);
        }
        &-tail {
            display: inline-block;
            @include sizeSet(21px, 16.5px);
            background-image: url(../../images/ko/showroom/srcomm/icon-speech-bubble-tail.png);
            background-repeat: no-repeat;
            @include absolute(bottom 0);
            &.right {
                right: 30%;
                background-position: 0 0;
            }
            &.left {
                left: 19%;
                background-position: -22px 0;
            }
        }
    }

    // floating 툴팁
    [data-tooltip-wrap] {
        position: relative;
        [data-tooltip] {
            @include absolute(left 50% top 20px);
            transform: translateX(-50%);
            &.show {
                [data-tooltip-text] {
                    display: block;
                    width: 290px;
                }
            }
            [data-tooltip-text] {
                display: none;
            }
        }
        &[data-tooltip-bottom] {
            [data-tooltip] {
                top: unset;
                bottom: 20px;
            }
            .sr-float-tooltip {
                &:before {
                    @include pseudo;
                    border-bottom: 7px solid rgba(36, 83, 204, 0.9);
                    border-left: 6px solid transparent;
                    border-right: 6px solid transparent;
                    top: unset;
                    bottom: -10px;
                    left: 50%;
                    transform: translateX(-50%) scaleY(-1);
                }
            }
        }
    }
    .sr-float-tooltip {
        background: rgba(36, 83, 204, 0.9);
        border-radius: 4px;
        width: max-content;
        z-index: 5;
        box-shadow: 0px 10px 15px 0px rgba(0, 0, 0, 0.15);
        &.show {
            width: 290px;
            [data-tooltip-title] {
                &:after {
                    transform: rotate(45deg);
                }
                p {
                    &:after {
                        display: none;
                    }
                }
            }
        }
        &:before {
            @include pseudo;
            border-bottom: 7px solid rgba(36, 83, 204, 0.9);
            border-left: 6px solid transparent;
            border-right: 6px solid transparent;
            top: -10px;
            left: 50%;
            transform: translateX(-50%);
        }
        [data-tooltip-title] {
            @include flex(center, null);
            width: 100%;
            text-align: left;
            padding: 11px 26px 9px 14px;
            position: relative;
            p {
                font-size: 18px;
                // font-weight: 700;
                color: $white;
                line-height: 1;
                position: relative;
                margin-right: 8px;
                padding-right: 10px;
                &:after {
                    @include pseudo;
                    @include sizeSet(1px, 14px);
                    background: rgba(0, 0, 0, 0.1);
                    right: 0;
                    top: 50%;
                    margin-top: -7px;
                }
            }
            &:after {
                @include sizeSet(18px, 18px);
                @include pseudo;
                right: 8px;
                top: 50%;
                margin-top: -9px;
                background: url(../../images/ko/showroom/srcomm/icon-plus-white.png) no-repeat 50% / 18px 18px;
            }
        }
        [data-tooltip-text] {
            padding: 8px 14px 18px;
            > p {
                font-size: 18px;
                line-height: 1.2;
                color: rgba(200, 228, 255, 1);
                font-weight: 400;
            }
        }
    }

    .sr-toast-msg {
        border-radius: 8px;
        padding: 24px 32px;
        line-height: 1;
        display: inline-block;
        @include absolute(top 50% left 50%);
        transform: translate(-50%, -50%);
        z-index: 50;
        width: max-content;
        transition: 1s;
        overflow: hidden;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        // backdrop-filter: blur(2px);
        &.active {
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
        &:has(br) {
            line-height: 1.3;
        }
        &:before {
            content: '';
            display: inline-block;
            @include absolute(top 0 right 0 bottom 0 left 0);
            backdrop-filter: blur(2px);
            background: rgba(36, 36, 36, 0.8);
            z-index: -1;
        }
        p {
            font-size: 20px;
            font-weight: 700;
            color: $white;
            > strong {
                color: #2b9eff;
                font-weight: inherit;
            }
        }
    }

    // Alert 메시지
    .sr-alert-msg {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        &.active {
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
        &:has(.complete) {
            > p {
                background: #1fb279;
            }
            i {
                background: url(../../images/ko/showroom/srcomm/icon-complete.png) no-repeat 50% / 24px 24px;
            }
        }
        &:has(.error) {
            > p {
                background: #c8001e;
            }
            i {
                background: url(../../images/ko/showroom/srcomm/icon-error.png) no-repeat 50% / 24px 24px;
            }
        }
        > p {
            padding: 10px 18px;
            line-height: 24px;
            border-radius: 50px;
            font-size: 18px;
            font-weight: 600;
            color: $white;
        }
        i {
            display: inline-block;
            vertical-align: top;
            @include sizeSet(24px, 24px);
            margin-right: 2px;
        }
    }

    // 누수 감시센서
    .sr-lk-sensor {
        position: relative;
        @include sizeSet(126.5px, 111px);
        &-round {
            // position: relative;
            .sr-lk-sensor-item {
                background: url(../../images/ko/showroom/srcomm/img-radar-item.png) no-repeat 50% / 30px;
                @include sizeSet(30px, 47px);
                z-index: 1;
                transform: unset;
                position: static;
            }
        }
        &-item {
            width: 24%;
            height: 37%;
            background: url(../../images/ko/showroom/srcomm/img-radar-item.png) no-repeat 50% / 100% 100%;
            @include absolute(left 50% top 0);
            transform: translateX(-50%);
        }
        &-beam {
            width: 100%;
            height: 68%;
            background: url(../../images/ko/showroom/srcomm/img-radar-beam.png) no-repeat 50% / 100% 100%;
            @include absolute(left 50% top 31.7%);
            transform: translateX(-50%);
        }
    }

    // 애니메이션 팝업 - 공통
    .sr-popup {
        &-wrap {
            @include fixed(top 0 left 0 bottom 0 right 0);
            z-index: 30;
            // display: none;
            transition-duration: 0.5s;
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
            &.active {
                opacity: 1;
                visibility: unset;
                pointer-events: unset;
            }
        }
        &-inner {
            width: 820px;
            min-height: 490px;
            background: rgba(36, 36, 36, 0.7);
            border-radius: 20px;
            @include absolute(top 50% left 50%);
            transform: translate(-50%, -50%);
            padding: 24px 0 40px;
            text-align: center;
            z-index: 1;
            overflow: hidden;
            &:before {
                content: '';
                display: inline-block;
                backdrop-filter: blur(20px);
                background: rgba(36, 36, 36, 0.1);
                z-index: -1;
                @include absolute(top 0 right 0 bottom 0 left 0);
            }
        }
        &-content {
            @include sizeSet(auto, auto);
            margin: 0 auto;
        }
        &-frame {
            width: 594px;
            min-height: 318px;
            margin: 0 auto;
            position: relative;
        }
        &-text {
            font-size: 24px;
            line-height: 1.35;
            color: $white;
            margin-top: 20px;
            > em {
                font-weight: 700;
                color: #2b9eff;
            }
        }
        &-btn {
            font-size: 20px;
            font-weight: 700;
            color: $white;
            background: $primary;
            border-radius: 4px;
            @include sizeSet(210px, 50px);
            margin-top: 30px;
        }
    }

    // 빔 효과
    .sr-layer-beam {
        display: inline-block;
        @include sizeSet(600px, 611px);
        background: url(../../images/ko/showroom/srcomm/img-sr8-layer-beam-bg1.png) no-repeat 50% / cover;
        animation-name: srcmBeamEffect;
        animation-duration: 4s;
        animation-timing-function: linear;
        animation-iteration-count: infinite;
        @include elHide();
        &.active {
            @include elShow();
        }
    }

    @keyframes srcmBeamEffect {
        0% {
            background-image: url(../../images/ko/showroom/srcomm/img-sr8-layer-beam-bg1.png);
        }
        25% {
            background-image: url(../../images/ko/showroom/srcomm/img-sr8-layer-beam-bg2.png);
        }
        50% {
            background-image: url(../../images/ko/showroom/srcomm/img-sr8-layer-beam-bg3.png);
        }
        75% {
            background-image: url(../../images/ko/showroom/srcomm/img-sr8-layer-beam-bg4.png);
        }
        100% {
            background-image: url(../../images/ko/showroom/srcomm/img-sr8-layer-beam-bg5.png);
        }
    }
}

.wrap-online-showroom {
    position: relative;
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background-color: #000;
    overflow: hidden;
    .showroom-container-wrap {
        position: absolute;
        top: 0;
        left: 0;
        width: inherit;
        height: inherit;
        // width: 1920px;
        // height: 1080px;
        // top: 50%;
        // left: 50%;
        // transform-origin: 50% 50%;
        overflow: hidden;
    }

    .showroom-container-inner {
        position: relative;
        width: inherit;
        height: inherit;
    }

    .showroom-content-wrap {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-position: center center;
        background-size: cover;
        background-repeat: no-repeat;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        &.active {
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
        .showroom-content-inner {
            position: relative;
            width: 100%;
            height: 100%;
            .showroom-screen-wrap {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                .showroom-screen-inner {
                    position: relative;
                    width: 100%;
                    height: 100%;
                }
            }
        }
    }

    .page-screen {
        position: absolute;
        bottom: 32px;
        left: 32px;
        z-index: 10;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        &.active {
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
        li {
            ~ li {
                margin-top: 12px;
            }
        }
    }

    .title-showroom-content {
        display: block;
        font-family: 'Pretendard';
        font-weight: 400;
        font-size: 40px;
        line-height: 52px;
        letter-spacing: -0.3px;
        color: rgba(0, 0, 0, 1);
        .text-bold {
            font-family: 'Pretendard';
            font-weight: 800;
            font-size: 40px;
            letter-spacing: -0.3px;
            color: rgba(0, 0, 0, 1);
        }
        ~ .sub-con-text {
            margin-top: 16px;
        }
    }
    .sub-con-text {
        display: block;
        font-family: 'Pretendard';
        font-weight: 400;
        font-size: 20px;
        line-height: 26px;
        letter-spacing: -0.3px;
        color: rgba(0, 0, 0, 1);
    }

    .button-screen-wrap {
        width: 48px;
        height: 48px;
        border: 1px solid rgba(238, 238, 238, 0.8);
        background-color: rgba(255, 255, 255, 0.6);
        background-origin: border-box;
        background-clip: content-box, border-box;
        border-radius: 50%;
        box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
        .button-screen-inner {
            box-sizing: border-box;
            display: block;
            width: 100%;
            height: 100%;
            background-position: center center;
            background-repeat: no-repeat;
            background-size: 16px 16px;
        }

        // 공통 : 컨텐츠 페이지 뒤로가기 버튼
        &.page-back {
            position: absolute;
            top: 32px;
            left: 32px;
            z-index: 10;
            border-radius: 24px;
            transition-duration: 0.3s;
            font-size: 0;
            .button-screen-inner {
                display: inline-block;
                background-position: 15px 50%;
                background-image: url('../../images/ko/showroom/arrow_page_back.png');
                transition-duration: 0.3s;
                font-size: 0;
                overflow: hidden;
                .text {
                    // width: 0;
                    display: inline-block;
                    font-family: 'Pretendard';
                    font-weight: 700;
                    font-size: 14px;
                    line-height: 46px;
                    letter-spacing: -0.3px;
                    color: rgba(0, 0, 0, 1);
                    text-align: center;
                    white-space: nowrap;
                    -webkit-transition-duration: 0.3s;
                    -o-transition-duration: 0.3s;
                    transition-duration: 0.3s;
                    padding-left: 46px;
                    opacity: 0;
                    visibility: hidden;
                }
            }
            &:hover {
                // width: auto;
                // min-width: 48px;
                // width: 120px;
                background-color: rgba(238, 238, 238, 1);
                .button-screen-inner {
                    // width: inherit;
                    .text {
                        // width: inherit;
                        opacity: 1;
                        visibility: unset;
                        padding-right: 18px;
                    }
                }
            }
        }
        // 가격견적 화면 Intro 가는 버튼
        &.page-intro {
            position: absolute;
            top: 32px;
            left: 97px;
            z-index: 10;
            border-radius: 24px;
            transition-duration: 0.3s;
            font-size: 0;
            .button-screen-inner {
                display: inline-block;
                background-size: 32px 32px;
                background-position: center 6px;
                background-image: url('../../images/ko/showroom/arrow_intro_back.png');
                background-repeat: no-repeat;
                transition-duration: 0.3s;
                font-size: 0;
                overflow: hidden;
                .text {
                    // width: 0;
                    display: inline-block;
                    font-family: 'Pretendard';
                    font-weight: 700;
                    font-size: 14px;
                    line-height: 46px;
                    letter-spacing: -0.3px;
                    color: rgba(0, 0, 0, 1);
                    text-align: center;
                    white-space: nowrap;
                    -webkit-transition-duration: 0.3s;
                    -o-transition-duration: 0.3s;
                    transition-duration: 0.3s;
                    padding-left: 46px;
                    opacity: 0;
                    visibility: hidden;
                }
            }
            &:hover {
                // width: auto;
                // min-width: 48px;
                // width: 120px;
                background-color: rgba(238, 238, 238, 1);
                .button-screen-inner {
                    // width: inherit;
                    .text {
                        // width: inherit;
                        opacity: 1;
                        visibility: unset;
                        padding-right: 18px;
                    }
                }
            }
        }

        // 공통 : 컨텐츠 페이지 확대 버튼
        &.page-screen-plus {
            .button-screen-inner {
                background-image: url('../../images/ko/showroom/icon-plus.png');
            }
        }

        // 공통 : 컨텐츠 페이지 축소 버튼
        &.page-screen-minus {
            .button-screen-inner {
                background-image: url('../../images/ko/showroom/icon-minus.png');
            }
        }
    }

    .bottom-gray-tooltip-wrap {
        position: absolute;
        left: 50%;
        transform: translateX(-50%);
        bottom: 0;
        display: inline-block;
        background-color: rgba(36, 36, 36, 0.7);
        padding: 24px 32px;
        border-radius: 8px;
        z-index: 30;
        transition-duration: 0.3s;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        &.active {
            bottom: 80px;
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
        .bottom-gray-text {
            display: none;
            white-space: nowrap;
            vertical-align: middle;
            font-family: 'Pretendard';
            font-weight: 400;
            font-size: 26px;
            line-height: 34px;
            letter-spacing: -0.3px;
            color: rgba(255, 255, 255, 1);
            text-align: center;
            &:has(br) {
                line-height: 1.3;
            }
            .color-bold-blue {
                font-weight: 700;
                font-size: 26px;
                color: rgba(43, 158, 255, 1);
            }
            &.active {
                display: inline-block;
            }
        }
    }

    // 컨텐츠 상단 탭 : 쇼룸 보기, 가격 견적
    .showroom-top-tab-wrap {
        position: absolute;
        top: 32px;
        left: 50%;
        transform: translateX(-50%);
        box-sizing: border-box;
        display: black;
        width: 330px;
        height: 48px;
        border-radius: 24px;
        border-top: 1px solid rgba(255, 255, 255, 1);
        background-color: rgba(255, 255, 255, 0.6);
        padding: 4px;
        opacity: 0;
        visibility: hidden;
        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
        &.active {
            z-index: 20;
            opacity: 1;
            visibility: unset;
        }
        .showroom-top-tab-inner {
            position: relative;
            height: 100%;
            .showroom-top-tab-list {
                position: relative;
                display: flex;
                height: 100%;
                z-index: 2;
                > li {
                    width: 100%;
                    &.active {
                        .button-tab {
                            .text {
                                color: rgba(29, 108, 235, 1);
                            }
                        }
                    }
                    .button-tab {
                        width: 100%;
                        height: 100%;
                        .text {
                            display: block;
                            font-family: 'Pretendard';
                            font-weight: 700;
                            font-size: 20px;
                            line-height: 22px;
                            letter-spacing: -0.3px;
                            color: rgba(0, 0, 0, 1);
                            text-align: center;
                            transition-duration: 0.3s;
                        }
                    }
                }
            }
            .button-bg {
                position: absolute;
                top: 0;
                left: 0;
                z-index: 1;
                display: block;
                width: 161px;
                height: 100%;
                border-radius: 20px;
                background-color: rgba(255, 255, 255, 1);
                transition-duration: 0.3s;
                box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05);
            }
        }
    }

    .speech-bubble-wrap {
        position: absolute;
        display: inline-block;
        font-size: 0;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        transition-duration: 0.3s;
        .speech-bubble-inner {
            display: inline-block;
            position: relative;
            padding-bottom: 9px;
            font-size: 0;
            filter: drop-shadow(0 0 2px rgba(0, 0, 0, 0.3));
            .sb-text {
                position: relative;
                display: inline-block;
                font-family: 'Pretendard';
                font-weight: 700;
                font-size: 14px;
                line-height: 1;
                letter-spacing: -0.3px;
                color: #000000;
                text-align: center;
                white-space: nowrap;
                z-index: 1;
                padding: 17px 23px 15px;
            }
            .speech-bubble-box-wrap {
                display: inline-block;
                opacity: 0.8;
                .speech-bubble-box {
                    position: absolute;
                    top: 0;
                    left: 0;
                    bottom: 9px;
                    width: 100%;
                    display: block;
                    padding: 17px 23px 19px;
                    height: 46px;
                    border-radius: 23px;
                    background-color: rgba(255, 255, 255, 1);
                    text-align: center;
                    font-size: 0;
                }
                .speech-bubble-tail {
                    position: absolute;
                    left: 24%;
                    bottom: 0;
                    width: 14px;
                    height: 10px;
                    display: inline-block;
                    background-position: center center;
                    background-repeat: no-repeat;
                    background-size: contain;
                    background-image: url('../../images/ko/showroom/speech_bubble_tail.png');
                }
            }
        }
    }

    .title-sign {
        position: absolute;
        top: 0;
        left: 50%;
        display: inline-block;
        text-align: center;
        font-size: 0;
        &.type-blue {
            .sign-box {
                background-color: rgba(36, 83, 204, 1);
                .sign-text {
                    color: #ffffff;
                }
            }
            &::after {
                border-top: 8px solid rgba(36, 83, 204, 1);
            }
        }
        .sign-box {
            display: block;
            min-width: 82px;
            text-align: center;
            background-color: rgba(255, 255, 255, 0.9);
            padding: 8px 14px;
            border-radius: 4px;
            box-shadow: 0 12px 12px rgba(0, 0, 0, 0.15);
            transition-duration: 0.3s;
            .sign-text {
                display: inline-block;
                font-family: 'Pretendard';
                font-weight: 700;
                font-size: 16px;
                line-height: 21px;
                letter-spacing: -0.3px;
                color: rgba(0, 0, 0, 1);
                text-align: center;
                transition-duration: 0.3s;
            }
        }
        &::after {
            margin-top: 5px;
            display: block;
            content: '';
            width: 0px;
            height: 0px;
            border-top: 8px solid rgba(255, 255, 255, 1);
            border-left: 6px solid transparent;
            border-right: 6px solid transparent;
            margin-left: auto;
            margin-right: auto;
            transition-duration: 0.3s;
        }
    }

    // 접근성 블라인드
    .blind {
        position: absolute;
        width: 1px;
        height: 1px;
        clip: rect(0 0 0 0);
        overflow: hidden;
    }

    .showroom-background-area {
        position: absolute;
        background-repeat: no-repeat;
        .showroom-background-layer {
            background-repeat: no-repeat;
        }
    }

    .showroom-background-dim {
        position: fixed;
        z-index: 2;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-repeat: no-repeat;
        background-position: center center;
        background-size: cover;
        //background-color: rgba(0, 0, 0, 0.3);
        pointer-events: none;
    }
}
