// 김현기(전용) 공통추가 충돌방지
.wrap-online-showroom {
    * {
        font-family: 'Pretendard';
    }
    .showroom-content-wrap {
        .showroom-content-inner {
            .showroom-content-mark {
                box-sizing: border-box;
                position: absolute;
                top: 0;
                left: 0;
                width: inherit;
                height: inherit;
                // background-color: rgba(255, 0, 0, 0.1);
                border: 1px solid rgba(255, 0, 0, 0.6);
                pointer-events: none;
                opacity: 1;
                z-index: 100;
            }
        }
    }

