    .title-intro-prograss {
        display: block;
        font-size: 0;
        text-align: center;
        .logo {
            @include bgCenterSet;
            display: inline-block;
            width: 162px;
            height: 61px;
            background-image: url('../../images/ko/showroom/srcomm/s1-logo-char.svg');
        }
        ~ .sub-text-intro-prograss-wrap {
