    .button-intro-box-vc {
        font-size: 0;
        &.active {
            .icon-view-box4 {
                .icon-view-box4-inner {
                    .box {
                        transform: translate(-50%, -50%) scale(0);
                        opacity: 0;
                        visibility: hidden;
                        &.box1 {
                            top: 50%;
                            left: 50%;
                        }
                        &.box2 {
                            top: 50%;
                            right: 50%;
                        }
                        &.box3 {
                            bottom: 50%;
                            left: 50%;
                        }
                        &.box4 {
                            bottom: 50%;
                            right: 50%;
                        }
                    }
                }
            }
            .icon-view-close {
                transform: translateY(-50%) rotate(405deg);
                transition-duration: 0.3s;
                opacity: 1;
                visibility: unset;
            }
            .text {
                &.text1 {
                    opacity: 0;
                    visibility: hidden;
                    width: 0px;
                }
                &.text2 {
                    opacity: 1;
                    visibility: unset;
                    width: auto;
                }
            }
        }
        .button-intro-box-vc-inner {
            display: inline-block;
            position: relative;
            // height: 50px;
            // background-image: linear-gradient(180deg, rgba(247, 247, 247, 1) 0%, rgba(244, 244, 244, 1) 100%);
            border: 1px solid rgba(255, 255, 255, 1);
            border-radius: 28px;
            padding: 15px 31px 15px 55px;
            overflow: hidden;
            white-space: nowrap;
            font-size: 0;
            // box-shadow: 0 0 6px rgba(0, 0, 0, 0.05);
        }
        .icon-view-box4 {
            display: inline-block;
            position: absolute;
            top: 50%;
            left: 23px;
            transform: translateY(-50%) rotate(0deg);
            width: 24px;
            height: 24px;
            .icon-view-box4-inner {
                display: block;
                position: relative;
                width: inherit;
                height: inherit;
                font-size: 0;
                .box {
                    display: inline-block;
                    position: absolute;
                    box-sizing: border-box;
                    width: 8px;
                    height: 8px;
                    border: 2px solid rgba(255, 255, 255, 1);
                    transition-duration: 0.3s;
                    transform: translate(0%, 0%);
                    &.box1 {
                        top: 3px;
                        left: 3px;
                    }
                    &.box2 {
                        top: 3px;
                        right: 3px;
                    }
                    &.box3 {
                        bottom: 3px;
                        left: 3px;
                    }
                    &.box4 {
                        bottom: 3px;
                        right: 3px;
                    }
                }
            }
        }
        .icon-view-close {
            display: inline-block;
            position: absolute;
            top: 50%;
            left: 23px;
            transform: translateY(-50%) rotate(0deg);
            width: 24px;
            height: 24px;
            opacity: 0;
            visibility: hidden;
            .icon-view-close-inner {
                display: block;
                position: relative;
                width: inherit;
                height: inherit;
                .bar {
                    display: block;
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    width: 18px;
                    height: 2px;
                    background-color: rgba(255, 255, 255, 1);
                    transition-duration: 0.3s;
                    &.bar1 {
                        transform: translate(-50%, -50%) rotate(0deg);
                    }
                    &.bar2 {
                        transform: translate(-50%, -50%) rotate(90deg);
                    }
                }
            }
        }
        .text {
            width: auto;
            display: inline-block;
            font-family: 'Pretendard';
            font-size: 20px;
            font-weight: 500;
            line-height: 26px;
            letter-spacing: -0.5px;
            // color: rgba(0, 0, 0, 1);
            color: rgba(255, 255, 255, 1);
            white-space: nowrap;
            overflow: hidden;
            opacity: 1;
            visibility: unset;
            transition-duration: 0.3s;
            &.text2 {
                opacity: 0;
                visibility: hidden;
                width: 0px;
            }
        }
    }

    .intro-service-box-wrap {
        position: absolute;
        // bottom: calc(50% - 148px);
        left: 50%;
        // top: 50%;
        // transform: translate(-50%, -50%);
        transform: translateX(-50%);
        padding-top: 16%;
        .intro-service-box-inner {
            position: relative;
            text-align: center;
            font-size: 0;
            white-space: nowrap;
            width: 1152px;
            height: 510px;
            .intro-service-box-item-wrap {
                display: inline-block;
                .intro-service-box-item-inner {
                    position: relative;
                    .isbi-content-wrap {
                        .isbi-content-inner {
                            position: relative;
                            border-radius: 12px;
                            overflow: hidden;
                            width: 568px;
                            height: 510px;
                            box-sizing: border-box;
                            .isbi-content-list {
                                position: absolute;
                                z-index: 3;
                                top: 0;
                                left: -100px;
                                width: 100%;
                                height: 100%;
                                padding: 36px 56px;
                                box-sizing: border-box;
                                opacity: 0;
                                visibility: hidden;
                                transition-duration: 0.3s;
                                .title-intro-service-box {
                                    text-align: left;
                                }
                                .service-box-link-list {
                                    > li {
                                        .service-box-link {
                                            text-align: left;
                                        }
                                    }
                                }
                            }
                            .bg-service-box-dim {
                                position: absolute;
                                z-index: 2;
                                top: 0;
                                left: 0;
                                width: 100%;
                                height: 100%;
                                display: block;
                                pointer-events: none;
                                background-color: rgba(0, 0, 0, 0);
                                transition-duration: 0.3s;
                            }
                            .bg-service-box-item {
                                position: absolute;
                                z-index: 1;
                                top: 50%;
                                left: 50%;
                                width: 120%;
                                height: 120%;
                                transform: translate(-50%, -50%);
                                display: block;
                                pointer-events: none;
                                background-repeat: no-repeat;
                                transition-duration: 0.3s;
                                filter: blur(0px);
                                &.bg-service-box-item1 {
                                    background-position: -322px -222px;
                                    background-size: 1311px 820px;
                                    background-image: url('../../images/ko/showroom/sr0/bg-service-box-item1.jpg');
                                }
                                &.bg-service-box-item2 {
                                    // background-position: -380px 20px;
                                    // background-size: 1137px 1016px;
                                    background-size: 87% 100%;
                                    background-position: calc(100% - 48px) bottom;
                                    background-image: url('../../images/ko/showroom/sr0/bg-service-box-item2.jpg');
                                }
                            }
                        }
                    }
                    .isbi-content-shadow {
                        position: absolute;
                        bottom: -135px;
                        left: 50%;
                        transform: translateX(-50%);
                        width: 640px;
                        height: 62px;
                        background-repeat: no-repeat;
                        background-position: center center;
                        background-size: 100% 100%;
                        background-image: url('../../images/ko/showroom/sr0/isbi-content-shadow.png');
                        filter: blur(15px);
                        pointer-events: none;
                    }
                }
            }
        }
    }

