    .service-box-link-list {
        > li {
            text-align: left;
            font-size: 0;
            .service-box-link {
                position: relative;
                display: inline-block;
                font-size: 0;
                opacity: 0.6;
                &.link-active {
                    opacity: 1;
                    &::after {
                        display: block;
                        content: '';
                        position: absolute;
                        bottom: 0;
                        left: 0;
                        transition-duration: 0.3s;
                        width: 0;
                        height: 1px;
                        background-color: rgba(255, 255, 255, 1);
                    }
                    &:hover {
                        &::after {
                            width: 100%;
                        }
                    }
                }
                .text {
                    display: inline-block;
                    vertical-align: middle;
                    font-family: 'Pretendard';
                    font-size: 24px;
                    font-weight: 400;
                    line-height: 30px;
                    letter-spacing: -0.3px;
                    color: rgba(255, 255, 255, 1);
                    ~ .icon {
                        margin-left: 8px;
                    }
                }
                .icon {
                    display: inline-block;
                    vertical-align: middle;
                    background-repeat: no-repeat;
                    background-position: center center;
                    background-size: contain;
                    &.right-arrow {
                        width: 10px;
                        height: 10px;
                        background-image: url('../../images/ko/showroom/srcomm/icon-intro-right-arrow.svg');
                    }
                    &.right-top-arrow {
                        width: 12px;
                        height: 12px;
                        background-image: url('../../images/ko/showroom/srcomm/icon-intro-right-top-arrow.svg');
                    }
                    &.play-movie {
                        width: 24px;
                        height: 24px;
                        background-image: url('../../images/ko/showroom/srcomm/icon-intro-play-movie.svg');
                    }
                }
            }
            ~ li {
                margin-top: 30px;
            }
        }
    }

