// [단독주택] : /showroom/house.html

.sr1-house {
    // [단독주택] .sr1-house Start
    background-color: rgba(226, 226, 226, 1);

    // [공동주택] 컨텐츠 showroom-content-wrap2
    .showroom-content-mark {
        border: 0 !important;
    }

    // 우측 스텝 메뉴 초기셋팅
    .service-step-wrap {
        opacity: 0;
        visibility: hidden;
        top: 52%;
    }

    // [단독주택] 컨텐츠 showroom-content-wrap1
    .showroom-content-wrap1 {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;
    }

    // 배경 : 인테리어, 딤 기본설정
    .showroom-background {
        // 이미지
        &-area {
            position: absolute;
            width: 1920px;
            height: 1080px;
            top: 50%;
            left: 50%;
        }
        &-inner {
            position: relative;
            width: inherit;
            height: inherit;
        }
        // 배경 인테리어
        &-layer {
            position: absolute;
            top: 58px;
            left: -35px;
            width: 2000px;
            height: 1148px;
            background-image: url('../../images/ko/showroom/sr1/bg-sr1-interior0-1.jpg');
            transform: scale(1);
            // opacity: 0;
            // visibility: hidden;
        }
        // 딤 : 배경 어둠/밝기
        &-dim {
            background-image: url('../../images/ko/showroom/sr1/bg-sr1-dimm0-1.png');
            opacity: 0;
            visibility: hidden;
        }
    }

    // 스와이퍼 썸네일 이미지
    .swiper-layer-wrap {
        &.swiper-layer-wrap2 {
            .thumbnail-wrap {
                &.thumbnail-wrap1 {
                    background-image: url('../../images/ko/showroom/thumbnail/sr-cctv-item01-01.jpg');
                }
                &.thumbnail-wrap2 {
                    background-image: url('../../images/ko/showroom/thumbnail/sr-cctv-item01-02.jpg');
                }
                &.thumbnail-wrap3 {
                    background-image: url('../../images/ko/showroom/thumbnail/sr-cctv-item01-03.jpg');
                }
            }
        }
    }
    // 스와이퍼 썸네일 이미지 버튼 눌렀을 경우 안보이게
    .iframe-video.active + .thumbnail-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }
    // 안심
    .popup-check-complete-wrap {
        position: absolute;
        z-index: 25;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        width: 282px;
        height: 280px;
        &.popup-check-complete-wrap1 {
            top: 512px;
            left: 913px;
            & .bg-check-complete {
                background-image: url('../../images/ko/showroom/srcomm//bg-popup-sr1-completer-screen1.png');
            }
        }
        &.popup-check-complete-wrap2 {
            top: 343px;
            left: 327px;
            & .bg-check-complete {
                background-image: url('../../images/ko/showroom/srcomm//bg-popup-sr1-completer-screen2.png');
            }
        }
        &.check-complete {
            transition-delay: 1s;
            transition-duration: 1s;
            opacity: 1;
            visibility: unset;
            pointer-events: unset;
        }
    }

    // 기본 셋팅
    .showroom-screen-wrap {
        opacity: 0;
        visibility: hidden;
        .showroom-step-wrap {
            opacity: 0;
            visibility: hidden;
        }
    }

    // 알람 문구
    .bottom-gray-tooltip-wrap-sr1-st2-1 {
        transition-duration: 0s;
    }
    .bottom-gray-tooltip-wrap-sr1-st2-2 {
        transition-duration: 0s;
    }
    .bottom-gray-tooltip-wrap-sr1-st2-3 {
        transition-duration: 0s;
    }

    // 강도
    .sr-thief-house {
        display: inline-block;
        background-repeat: no-repeat;
        background-position: center center;
        background-size: contain;
        position: absolute;
        opacity: 0;
        visibility: hidden;
    }

    // 경고문구
    .sr-warning-red-wrap {
        .sr-warning-red {
            opacity: 0;
            visibility: hidden;
            transition-duration: 0.6s;
            display: inline-block;
            position: absolute;
            z-index: 10;
            > p {
                font-size: 18px;
                font-weight: 700;
                border-radius: 50px;
                padding: 10px 18px;
                color: #fff;
                background-color: #c8001e;
                i {
                    background: url('../../images/ko/showroom/srcomm/icon-warning.png') no-repeat 50% / 24px 24px;
                    display: inline-block;
                    vertical-align: middle;
                    width: 24px;
                    height: 24px;
                    margin-right: 5px;
                    margin-bottom: 2px;
                }
            }
            &.sr-warning-red1 {
                top: 292px;
                left: 577.72px;
            }
            &.sr-warning-red2 {
                top: 226.84px;
                left: 648.77px;
            }
            &.sr-warning-red3 {
                top: 297px;
                left: 604.89px;
            }
            &.sr-warning-red4 {
                top: 595.34px;
                left: 187.17px;
            }
        }
    }

    // 팝업
    .popup-layer-animation-wrap {
        position: absolute;
        opacity: 0;
        visibility: hidden;
        top: 52%;
        left: 50%;
        transform: translate(-50%, -50%);
        z-index: 2;
        transition-duration: 0s;
    }

    // 출동경비 서비스 0911 팝업
    .popup-layer-animation-wrap1 {
        &.popup-layer-animation-wrap {
            display: inline-block;
            border-radius: 20px;
            width: 820px;
            height: 490px;
            margin-left: auto;
            margin-right: auto;
            font-size: 0;

            .popup-layer-animation-inner {
                display: inline-block;
                position: relative;
                width: inherit;
                height: inherit;
                font-size: 0;
                border-radius: inherit;
                overflow: hidden;
                &::before {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    width: 120%;
                    height: 120%;
                    transform: translate(-50%, -50%);
                    display: block;
                    content: '';
                    background-color: rgba(36, 36, 36, 0.95);
                    filter: blur(10px);
                }
                .animation-box-wrap {
                    position: absolute;
                    top: 0;
                    left: 0;
                    right: 0;
                    height: 318px;
                    font-size: 0;
                    &.control-center {
                        .icon-postion-wrap {
                            position: absolute;
                            z-index: 1;
                            .icon-postion-inner {
                                position: relative;
                                .ani-icon-secom {
                                    position: relative;
                                    z-index: 1;
                                }
                                .ellipse-wave-length-wrap {
                                    left: 50%;
                                    transform: translateX(-50%);
                                    &.ellipse-wave-length-wrap1 {
                                        // bottom: -6px;
                                    }
                                    &.ellipse-wave-length-wrap2 {
                                        bottom: -14px;
                                    }
                                }
                            }
                            &.top-center {
                                top: 55.04px;
                                left: 50%;
                                transform: translateX(-50%);
                            }
                            &.bottom-left {
                                top: 185px;
                                left: 100px;
                            }
                            &.bottom-left-top {
                                top: 45px;
                                left: 160px;
                            }
                            &.bottom-center {
                                top: 196px;
                                left: 50%;
                                transform: translateX(-50%);
                                .ani-icon-name {
                                    bottom: -16px;
                                }
                            }
                            &.bottom-right-top {
                                top: 45px;
                                right: 160px;
                            }
                            &.bottom-right {
                                top: 186px;
                                right: 100px;
                            }
                            .ani-icon-name {
                                @include elHide();
                            }
                        }
                        .line-dot-red {
                            position: absolute;
                            display: inline-block;
                            bottom: 45px;
                            .line-dot-view {
                                display: inline-block;
                                background-repeat: repeat;
                                background-size: 10px 10px;
                                background-image: url('../../images/ko/showroom/srcomm/bg-line-dot-scarlet.png');
                            }
                            &.center-width {
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                                &.center-width-left {
                                    left: 200px;
                                }
                                &.center-width-right {
                                    right: 200px;
                                }
                                &.center-width-left-top {
                                    left: 247px;
                                    bottom: 185px;
                                    transform: rotate(41deg);
                                    transform-origin: 0 0;
                                }
                                &.center-width-right-top {
                                    right: 247px;
                                    bottom: 185px;
                                    transform: rotate(-41deg);
                                    transform-origin: 100% 0;
                                }
                            }
                            &.center-bottom-top {
                                left: 50%;
                                transform: translate(-50%);
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                            }
                        }
                    }
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            position: absolute;
                            width: 96px;
                            height: 184px;
                            .sr-person-dm-inner {
                                position: relative;
                                .icon-ex-mark-speech-bubble {
                                    position: absolute;
                                    top: -24.92px;
                                    right: -46.94px;
                                }
                            }
                        }
                        .img-dispatch-vehicle {
                            position: absolute;
                        }
                    }
                    .animation-box-inner {
                        position: relative;
                        width: 100%;
                        height: 100%;
                        > div:not(.top-center) {
                            width: 170px;
                            height: 100px;
                            display: flex;
                            align-items: flex-end;
                            justify-content: center;
                        }
                    }
                }
                .bottom-text-wrap {
                    display: block;
                    position: absolute;
                    left: 115px;
                    right: 115px;
                    text-align: center;
                    .text {
                        display: inline-block;
                        font-family: 'Pretendard';
                        font-size: 26px;
                        font-weight: 400;
                        line-height: 130%;
                        letter-spacing: -0.3px;
                        color: rgba(255, 255, 255, 1);
                        .color-blue {
                            font-family: 'Pretendard';
                            font-size: 26px;
                            font-weight: 700;
                            letter-spacing: -0.3px;
                            color: rgba(43, 158, 255, 1);
                        }
                    }
                }
            }

            .bottom-text-wrap {
                bottom: 0px;
                opacity: 0;
                visibility: hidden;
                transition-duration: 0.6s;
            }

            .animation-box-wrap {
                &.control-center {
                    .icon-postion-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                    }

                    .ellipse-wave-length-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                        .ellipse-wave-item {
                            animation-timing-function: linear;
                            animation-duration: 1s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                    }

                    .line-dot-red {
                        .line-dot-view {
                            animation-timing-function: linear;
                            animation-direction: normal;
                            animation-iteration-count: infinite;
                        }
                        &.center-width {
                            width: 0px;
                            height: 2px;
                            transition-duration: 0s;
                            &.center-width-left {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                            &.center-width-left-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                        }
                        &.center-bottom-top {
                            width: 2px;
                            height: 0px;
                            transition-duration: 0s;
                            .line-dot-view {
                                animation-duration: 3s;
                                background-position: center 100%;
                            }
                        }
                    }
                }
                &.dispatch-immediately {
                    overflow: hidden;
                    .sr-person-dm-wrap {
                        opacity: 0;
                        visibility: hidden;
                        top: 130.92px;
                        left: 279.5px;
                        width: 96px;
                        height: 184px;
                    }
                    .icon-ex-mark-speech-bubble {
                        opacity: 0;
                        visibility: hidden;
                    }
                    .img-dispatch-vehicle {
                        opacity: 0;
                        visibility: hidden;
                        top: 159.67px;
                        left: 500px;
                        .di-car-siren-machine {
                            top: 18.07px;
                            left: 172.56px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-siren-light {
                            top: 0px;
                            left: 109.54px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-body {
                            top: 33.27px;
                            left: 0.45px;
                            animation-timing-function: linear;
                            animation-duration: 2s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-exhaust {
                            .di-car-exhaust-bar {
                                left: -100%;
                                animation-timing-function: linear;
                                animation-duration: 1s;
                                animation-direction: normal;
                                animation-iteration-count: infinite;
                            }
                            &.di-car-exhaust1 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0s;
                                }
                            }
                            &.di-car-exhaust2 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0.1s;
                                }
                            }
                        }
                    }
                }
            }

            // .popup-layer-animation-wrap에 active시 동작하나 이것을 페이지 step을 타고 걸어주면 된다.
            &.active {
                opacity: 1;
                visibility: unset;
                pointer-events: unset;
                transition-duration: 0.5s;
                .bottom-text-wrap {
                    bottom: 60px;
                    opacity: 1;
                    visibility: unset;
                    transition-delay: 0.5s;
                }
                .animation-box-wrap {
                    // 에스원 관제센터 active
                    &.control-center {
                        .icon-postion-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 0.3s;
                            &.bottom-left {
                                transition-delay: 1s;
                            }
                            &.bottom-right {
                                transition-delay: 1s;
                            }
                            &.bottom-left-top {
                                transition-delay: 1s;
                            }
                            &.bottom-right-top {
                                transition-delay: 1s;
                            }
                            &.bottom-center {
                                transition-delay: 1.5s;
                            }
                            &.top-center {
                                transition-delay: 2s;
                            }
                        }

                        .ellipse-wave-length-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 1s;
                            &.ellipse-wave-length-wrap1 {
                                transition-delay: 2.5s;
                            }
                            &.ellipse-wave-length-wrap2 {
                                transition-delay: 2.5s;
                            }
                            .ellipse-wave-item {
                                transform: translate(-50%, -50%) scale(0);
                                animation-delay: 3s;
                                animation-name: ellipseWaveItem1;
                            }
                        }

                        .line-dot-red {
                            &.center-width {
                                width: 213px;
                                height: 2px;
                                transition-delay: 3s;
                                transition-duration: 1s;
                                &.center-width-left {
                                    .line-dot-view {
                                        animation-name: centerWidthLeft;
                                    }
                                }
                                &.center-width-right {
                                    .line-dot-view {
                                        animation-name: centerWidthRight;
                                    }
                                }
                            }
                            &.center-bottom-top {
                                width: 2px;
                                height: 98px;
                                transition-delay: 3.5s;
                                transition-duration: 1s;
                                .line-dot-view {
                                    animation-name: centerBottomTop;
                                }
                            }
                        }
                    }

                    // 즉시 현장으로 출동 active
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            opacity: 1;
                            visibility: unset;
                            left: 179.5px;
                            transition-delay: 3s;
                            transition-duration: 1s;
                        }
                        .icon-ex-mark-speech-bubble {
                            opacity: 1;
                            visibility: unset;
                            transition-delay: 2s;
                            transition-duration: 1s;
                        }
                        .img-dispatch-vehicle {
                            opacity: 1;
                            visibility: unset;
                            left: 287.53px;
                            transition-delay: 4s;
                            transition-duration: 0.5s;
                            .di-car-siren-light {
                                animation-name: diCarSirenLight;
                            }
                            .di-car-exhaust {
                                .di-car-exhaust-bar {
                                    animation-name: diCarExhaust;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    .ani-icon-secom {
        display: inline-block;
        background-repeat: no-repeat;
        background-position: center center;
        background-size: contain;
        // 링크
        &-link {
            width: 100px;
            height: 50px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-center-pop.svg');
        }
        // 열선 감지기
        &-heat-detector {
            width: 58px;
            height: 120px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-01.svg');
        }
        // 움직임 감지기
        &-glass-detector {
            width: 56.34px;
            height: 86.52px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-02.svg');
        }
        // 문열림 감지기
        &-magnet-detector {
            bottom: 15px;
            width: 124px;
            height: 34px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-03.svg');
        }
        // 적외선 감지기
        &-infrared-detector {
            width: 30.12px;
            height: 81.57px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-04.svg');
            bottom: 8px;
            display: inline-block;
            position: absolute;
            z-index: 30;
            left: -15px;
        }
        // 금고 감지기
        &-safe-sensor {
            width: 55px;
            height: 76px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-05.svg');
            bottom: 6px;
            left: -2px;
        }
    }
    // 출동경비 서비스 0911 팝업

    // screen1 step 2-1
    .showroom-screen1-wrap {
        // screen1 - step2 아이콘 초기
        .showroom-step2-icon-layer-wrap {
            position: absolute;
            top: 107px;
            left: 212px;
            width: 1127px;
            height: 619px;
            .showroom-step2-icon-layer-inner {
                position: relative;
                width: 100%;
                height: 100%;
                .sr-circle-item {
                    position: absolute;
