                        & .img-secom-circle-item1 {
                            background-size: 42px 57px;
                            background-image: url(../../images/ko/showroom/sr1/circle/img-secom-circle-item1.png);
                        }
                    }
                    &.sr-circle-item2 {
                        top: 307px;
