// [가격견적] : /showroom/pricing.html

// 견적내기 컴포넌트
.estimate-indicator {
    display: inline-block;
    @include absolute(top 50% right 32px);
    transform: translateY(-50%);
    z-index: 20;
    &-inner {
        width: 332px;
        padding: 32px 8px 8px;
        border-radius: 20px;
        background-color: rgba(246, 246, 246, 0.75);
        border: 1px solid $white;
    }
    &-title {
        padding: 0 10px;
        @include flex(flex-end, space-between);
        > h4 {
            font-weight: 700;
            font-size: 26px;
            line-height: 1;
        }
        .button-reset {
            font-size: 14px;
            font-weight: 500;
            position: relative;
            padding: 6px 30px 6px 9px;
            background: rgba(198, 198, 198, 0.3);
            border-radius: 20px;
            line-height: 1;
            &:after {
                @include pseudo;
                @include sizeSet(17px, 18px);
                right: 9px;
                top: 50%;
                margin-top: -9px;
                background: url(../../images/ko/showroom/srcomm/icon-reset.png) no-repeat 50% / 17px 18px;
            }
        }
    }
    &-details {
        margin-top: 24px;
        border-radius: 12px;
        background-color: rgba(246, 246, 246, 0.75);
        border: 1px solid $white;
        padding: 28px 24px;
    }
    .select-details {
        &-item {
            &:last-of-type {
                border-bottom: 1px solid rgba(0, 0, 0, 0.1);
            }
            // 상세 내용 노출 상태
            &.open {
                .details-btn {
                    &:after {
                        transform: rotate(180deg);
                    }
                }
                .details-view {
                    padding-bottom: 18px;
                    // display: flex;
                    &:has(button.option) {
                        padding-bottom: 10px;
                    }
                }
            }
            // 선택 완료
            &.done {
                .details-btn {
                    &:after {
                        display: none;
                    }
                    em {
                        display: inline-block;
                    }
                }
            }
            // 비활성화 상태
            &.disabled {
                pointer-events: none;
                .details-btn {
                    opacity: 0.5;
                }
            }
            & + .select-details-item {
                border-top: 1px solid rgba(0, 0, 0, 0.1);
                .details-btn {
                    padding-top: 20px;
                }
            }
            // 장소
            &.place {
                .details-view {
                    // .option {
                    //     display: none;
                    // }
                    &.commercial {
                        .opt-house {
                            display: none;
                        }
                        .opt-cmsl {
                            display: inline-block;
                        }
                    }
                    &.household {
                        .opt-cmsl {
                            display: none;
                        }
                        .opt-house {
                            display: inline-block;
                        }
                    }
                }
            }
            .details {
                &-btn {
                    @include flex(center, space-between);
                    font-size: 16px;
                    line-height: 1;
                    width: 100%;
                    padding-bottom: 20px;
                    position: relative;
                    &:after {
                        @include pseudo;
                        @include sizeSet(24px, 24px);
                        background: url(../../images/ko/showroom/srcomm/icon-combo-arrow.png) no-repeat 50% / 100% 100%;
                        right: 0;
                    }
                    > p {
                        font-weight: 500;
                        text-align: left;
                        flex: 1;
                        letter-spacing: -0.5px;
                    }
                    > em {
                        font-weight: 700;
                        display: none;
                    }
                }
                &-view {
                    // display: flex;
                    display: none;
                    overflow: hidden;
                    flex-wrap: wrap;
                    justify-content: space-between;
                    &.l-grid-3 {
                        .option {
                            width: calc(33.3% - 5px);
                        }
                    }
                }
            }
            .option {
                width: calc(50% - 4px);
                margin-bottom: 8px;
                font-size: 14px;
                text-align: center;
                height: 50px;
                line-height: 48px;
                background: $white;
                border-radius: 4px;
                border: 1px solid #dcdcdc;
                &.selected {
                    border-color: $primary;
                    > span {
                        color: $primary;
                        font-weight: 700;
                    }
                }
            }
            // 출입문 개수
            .spinner {
                display: flex;
                font-size: 0;
                @include sizeSet(100%, 50px);
                border: 1px solid #dcdcdc;
                border-radius: 4px;
                overflow: hidden;
                > button,
                > input[type='number'] {
                    height: 100%;
                }
                > button {
                    width: 50px;
                    background: #f5f5f5;
                    background-repeat: no-repeat;
                    background-position: 50%;
                    &:disabled {
                        pointer-events: none;
                        opacity: 0.3;
                    }
                    &.decrease {
                        background-image: url(../../images/ko/showroom/srcomm/icon-minus.png);
                        background-size: 12px auto;
                    }
                    &.increase {
                        background-image: url(../../images/ko/showroom/srcomm/icon-plus.png);
                        background-size: 12px auto;
                    }
                }
                > input[type='number'] {
                    -moz-appearance: textfield;
                    font-size: 14px;
                    width: calc(100% - 100px);
                    background: $white;
                    text-align: center;
                    border-width: 0 1px;
                    border-style: solid;
                    border-color: #dcdcdc;
                    color: #353535;
                    line-height: 48px;
                    &.text-blue {
                        color: $primary;
                        font-weight: 700;
                    }
                    &::-webkit-outer-spin-button,
                    &::-webkit-inner-spin-button {
                        -webkit-appearance: none;
                        margin: 0;
                    }
                }
            }
        }
    }
    .select-result {
        p {
            margin-top: 8px;
            text-align: right;
            color: #c4c4c4;
            font-size: 24px;
            font-weight: 700;
            height: 36px;
            &.calculated {
                font-size: 20px;
                color: $black;
                > em {
                    font-size: 24px;
                    font-weight: inherit;
                }
            }
        }
        span {
            margin-top: 18px;
            font-size: 12px;
            color: #757575;
            line-height: 1.25;
            display: inline-block;
            + span {
                margin-top: 1px;
            }
        }
    }
    .button-submit {
        margin-top: 18px;
        width: 100%;
        display: block;
        text-align: center;
        color: $white;
        background: $primary;
        font-size: 20px;
        font-weight: 700;
        height: 48px;
        line-height: 46px;
        border-radius: 4px;
        &:disabled {
            border: 1px solid #d9d9d9;
            background: #e4e4e4;
            color: #9d9d9d;
        }
    }
}

// 첫 진입 시 효과
.sr-pricing {
    &.pr-store {
        &.pr-dimmed {
            .showroom-screen-wrap {
                &.active {
                    .showroom-step-wrap {
                        &.active {
                            .inner-frame {
                                &:before {
                                    top: -70px;
                                }
                                &:after {
                                    top: 46%;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    &.pr-dimmed {
        .showroom-screen-wrap {
            &.active {
                .showroom-step-wrap {
                    &.active {
                        .inner-frame {
                            &:before {
                                content: '';
                                display: inline-block;
                                @include absolute(top -20px right -20px bottom -20px left -20px);
                                z-index: 5;
                                background: rgba(0, 0, 0, 0.6);
                                filter: blur(5px);
                                backdrop-filter: blur(5px);
                                transition-duration: 0.2s;
                            }
                            &:after {
                                content: '오른쪽 리스트에서 옵션을 선택해주세요.';
                                display: inline-block;
                                @include absolute(top 50% left 50%);
                                transform: translate(-50%, -50%);
                                z-index: 10;
                                color: $white;
                                font-size: 22px;
                                font-weight: 700;
                            }
                        }
                    }
                }
            }
        }
        // &:after{

        // }
    }
    .estimate-indicator {
        opacity: 0;
        filter: blur(20px);
        transition: 1s opacity, filter;
    }
    .showroom {
        &-background-area {
            opacity: 0;
            filter: blur(20px);
            transition: 1s opacity, filter;
        }
    }
    &.main {
        .estimate-indicator {
            opacity: 1;
            filter: unset;
        }
        .showroom {
            &-background-area {
                opacity: 1;
                filter: unset;
            }
        }
    }
}

// [가격견적] .sr-pricing Start
// bg, bgSize 설정
$_places: (
    // 단독주택
    house: '1682px 946px',
    // 공동주택
    villa: '1700px 956.6px',
    // 매장
    store: '1724px 970px',
    // 사무실
    office: '1632px 918px',
    // 공장
    factory: '1653px 929px',
    // 창고
    storage: '1376px 774px'
);

.sr-pricing {
    background-color: rgba(226, 226, 226, 1);
    // bg 설정
    @each $class, $bgSize in $_places {
        &.pr-#{$class} {
            .showroom-background {
                &-layer {
                    background-image: url(../../images/ko/showroom/pricing/bg-srpr-interior-#{$class}.jpg);
                    background-size: #{$bgSize};
                }
            }
        }
    }
    .showroom-screen {
        &-wrap {
            // transition: 2s;
            @include elHide();
            &.active {
                @include elShow();
            }
        }
    }
    .showroom-step {
        &-wrap {
            height: 100%;
            @include absolute(top 0 right 0 bottom 0 left 0);
            height: 100%;
            @include elHide();
            &.active {
                @include elShow();
            }
        }
        &-inner {
            height: 100%;
            position: relative;
        }
    }
    .showroom-content-wrap-pr {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;
    }
    .showroom-background {
        &-area {
            @include sizeSet(1920px, 1080px);
            @include absolute(top 50% left 50%);
        }
        &-inner {
            position: relative;
            @include sizeSet(inherit, inherit);
        }
        &-layer {
            position: absolute;
            @include sizeSet(inherit, inherit);
            background-position: 50%;
            transform: scale(1);
            top: 14px;
            left: -8%;
            transition-duration: 0.5s;
            transition-property: background-image;
            transition-timing-function: ease-out;
        }
    }

    // 카테고리의 메인
    &.main {
        // 장소별 공통
        .showroom-background-layer {
            width: 100%;
            height: 100%;
            top: 0;
        }
        .inner-frame {
            // background: rgba(255, 0, 0, 0.2);
            position: absolute;
            top: 50%;
            transform: translate(-50%, -50%);
        }
        .door-wrap {
            .door {
                &-area {
                    @include sizeSet(120px, 120px);
                    position: absolute;
                    // opacity: 0;
                }
                &-item {
                    display: inline-block;
                    font-size: 0;
                    position: absolute;
                    @include elHide();
                    &.show {
                        // transition-duration: 0.3s;
                        @include elShow();
                    }
                    &.side-1 {
                        top: 0;
                        bottom: auto;
                    }
                    &.side-2 {
                        right: 0;
                        left: auto;
                        transform: scaleX(-1) rotate(0deg);
                    }
                    &.side-3 {
                        top: auto;
                        bottom: 0;
                        transform: rotate(180deg);
                        right: 0;
                        left: auto;
                    }
                    &.side-4 {
                        top: auto;
                        bottom: 0;
                        left: 0;
                        right: auto;
                        transform: scaleX(-1) rotate(180deg);
                    }
                    > i {
                        display: inline-block;
                        @include sizeSet(60px, 60px);
                        background: url(../../images/ko/showroom/pricing/img-srpr-door.png) no-repeat 50% / 60px 60px;
                    }
                }
                &-lock-item {
                    display: inline-block;
                    font-size: 0;
                    position: absolute;
                    filter: drop-shadow(2px 2px 4px rgba(0, 0, 0, 0.05));
                    @include elHide();
                    &.show {
                        transition-duration: 0.3s;
                        @include elShow();
                    }
                    // display: none;
                    > i {
                        display: inline-block;
                        font-size: 0;
                        background-repeat: no-repeat;
                        background-position: 50%;
                        background-color: $white;
                        border-radius: 50%;
                        @include sizeSet(80px, 80px);
                        border: 1px solid #cdd2de;
                        overflow: hidden;
                        transition: 0.3s;
                        &.finger {
                            background-image: url(../../images/ko/showroom/pricing/img-srpr-lock-finger.jpg);
                            background-size: 37px auto;
                        }
                        &.face {
                            background-image: url(../../images/ko/showroom/pricing/img-srpr-lock-face.jpg);
                            background-size: 28px auto;
                        }
                        &.card {
                            background-image: url(../../images/ko/showroom/pricing/img-srpr-lock-card.jpg);
                            background-size: 25px auto;
                        }
                    }
                }
            }
        }
        .cctv-wrap {
            @include elHide();
            &.active {
                transition-duration: 0.2s;
                @include elShow();
            }
            .cctv-item {
                display: inline-block;
                @include sizeSet(82px, 82px);
                border-radius: 50%;
                background: $white;
                position: absolute;
                border: 3px solid $primary;
                filter: drop-shadow(2px 2px 4px rgba(0, 0, 0, 0.05));
                &.show {
                    .cctv-item-layer {
                        opacity: 1;
                        button {
                            pointer-events: unset;
                        }
                    }
                }
                &:before,
                &:after {
                    @include pseudo;
                    background: $primary;
                    position: absolute;
                    left: 50%;
                    top: 50%;
                    z-index: 0;
                }
                &:before {
                    @include sizeSet(2px, 24px);
                    margin: -12px 0 0 -1px;
                }
                &:after {
                    @include sizeSet(24px, 2px);
                    margin: -1px 0 0 -12px;
                }
                &-layer {
                    opacity: 0;
                    button {
                        pointer-events: none;
                    }
                }
                &-img {
                    display: inline-block;
                    @include absolute(top 0 right 0 bottom 0 left 0);
                    background: $white url(../../images/ko/showroom/pricing/img-srpr-cctv.jpg) no-repeat 50%;
                    background-size: 64.7px auto;
                    z-index: 1;
                    border-radius: 50%;
                }
                button {
                    display: inline-block;
                    @include sizeSet(29px, 29px);
                    z-index: 1;
                    @include absolute(right 0 top 0);
                    background: $primary;
                    border-radius: 50%;
                    &:after {
                        @include pseudo;
                        @include sizeSet(12px, 2px);
                        background: $white;
                        top: 50%;
                        left: 50%;
                        margin: -1px 0 0 -6px;
                    }
                }
            }
        }
    }
    // 단독주택
    &.pr-house {
        .showroom-background-layer {
            background-size: 1682px 946px;
        }
        .inner-frame {
            @include sizeSet(1047px, 876px);
            left: calc(42% - 4px);
