// 파장
.skew-wavelength {
    // position: absolute;
    position: relative;
    display: inline-block;
    width: 120px;
    height: 120px;
    font-size: 0;
    &-inner {
        position: relative;
        display: inline-block;
        top: 0;
        left: 0;
        width: 120px;
        height: 120px;
        font-size: 0;
        // transform: perspective(30px) rotateY(-16deg) scale(1);
        transform: rotateY(-16deg) scale(0.8) skew(-35deg, 40deg);
    }
    &.active {
        .skew-wavelength-layer1 {
            animation-name: skWavelengthLayer1;
        }
        .skew-wavelength-layer2 {
            animation-name: skWavelengthLayer2;
        }
        .skew-wavelength-layer2 {
            animation-name: skWavelengthLayer3;
        }
    }
    &.blue {
        &.active {
            .skew-wavelength-layer1 {
                animation-name: skWavelengthLayer1;
            }
            .skew-wavelength-layer2 {
                animation-name: skWavelengthLayer2;
            }
            .skew-wavelength-layer3 {
                animation-name: skWavelengthLayer3;
            }
        }
        .skew-wavelength-layer {
            [class*='skew-wavelength-layer'] {
                background: $primary;
                background: radial-gradient(circle, rgba(29, 108, 235, 0) 0%, rgba(29, 108, 235, 0.3) 100%);
            }
        }
    }
    &-layer {
        &1 {
            width: 58px;
            height: 58px;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%) scale(0);
            border-radius: 50%;
            animation-iteration-count: infinite;
            animation-timing-function: ease-out;
            animation-duration: 1s;
            background-image: radial-gradient(circle, rgba(29, 108, 235, 0) 0%, rgba(29, 108, 235, 0.4) 100%);
        }
        &2 {
            width: 98px;
            height: 98px;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%) scale(0);
            border-radius: 50%;
            animation-iteration-count: infinite;
            animation-timing-function: ease-out;
            animation-duration: 1s;
            background-image: radial-gradient(circle, rgba(29, 108, 235, 0) 0%, rgba(29, 108, 235, 0.8) 100%);
        }
        &3 {
            width: 120px;
            height: 120px;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%) scale(0);
            border-radius: 50%;
            animation-iteration-count: infinite;
            animation-timing-function: ease-out;
            animation-duration: 1s;
            background-image: radial-gradient(circle, rgba(29, 108, 235, 0) 0%, rgba(29, 108, 235, 0.8) 100%);
        }
    }
}

// 포인터
@keyframes skWavelengthLayer1 {
    0% {
        transform: translate(-50%, -50%) scale(0);
    }
    80% {
        transform: translate(-50%, -50%) scale(1);
    }
    100% {
        transform: translate(-50%, -50%) scale(1);
        opacity: 1;
    }
}
@keyframes skWavelengthLayer2 {
    0% {
        transform: translate(-50%, -50%) scale(0);
    }
    80% {
        opacity: 0.4;
    }
    100% {
        transform: translate(-50%, -50%) scale(1);
        opacity: 0;
    }
}
@keyframes skWavelengthLayer3 {
    0% {
        transform: translate(-50%, -50%) scale(0);
    }
    80% {
        opacity: 0.4;
    }
    100% {
        transform: translate(-50%, -50%) scale(1);
        opacity: 0;
    }
}
