// [매장] : /showroom/store.html

.sr3-store {
    .showroom-content-mark {
        border: 0 !important;
    }

    // [매장] .sr3-store Start
    background-color: rgba(226, 226, 226, 1);

    // 우측 스텝 메뉴 초기셋팅
    .service-step-wrap {
        opacity: 0;
        visibility: hidden;
        top: 52%;
    }

    // [매장] 컨텐츠 showroom-content-wrap3
    .showroom-content-wrap3 {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;
    }

    // 스크린 공통
    .showroom-screen-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    // 스텝 공통
    .showroom-step-wrap {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 100%;
        height: 100%;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }
    // 출동경비 서비스 0911 팝업
    .popup-layer-animation-wrap1 {
        &.popup-layer-animation-wrap {
            display: inline-block;
            border-radius: 20px;
            width: 820px;
            height: 490px;
            margin-left: auto;
            margin-right: auto;
            font-size: 0;

            .popup-layer-animation-inner {
                display: inline-block;
                position: relative;
                width: inherit;
                height: inherit;
                font-size: 0;
                border-radius: inherit;
                overflow: hidden;
                &::before {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    width: 120%;
                    height: 120%;
                    transform: translate(-50%, -50%);
                    display: block;
                    content: '';
                    background-color: rgba(36, 36, 36, 0.95);
                    filter: blur(10px);
                }
                .animation-box-wrap {
                    position: absolute;
                    top: 0;
                    left: 0;
                    right: 0;
                    height: 318px;
                    font-size: 0;
                    &.control-center {
                        .icon-postion-wrap {
                            position: absolute;
                            z-index: 1;
                            .icon-postion-inner {
                                position: relative;
                                .ani-icon-secom {
                                    position: relative;
                                    z-index: 1;
                                }
                                .ellipse-wave-length-wrap {
                                    left: 50%;
                                    transform: translateX(-50%);
                                    &.ellipse-wave-length-wrap1 {
                                        // bottom: -6px;
                                    }
                                    &.ellipse-wave-length-wrap2 {
                                        bottom: -14px;
                                    }
                                }
                            }
                            &.top-center {
                                top: 55.04px;
                                left: 50%;
                                transform: translateX(-50%);
                            }
                            &.bottom-left {
                                top: 185px;
                                left: 100px;
                            }
                            &.bottom-left-top {
                                top: 45px;
                                left: 160px;
                            }
                            &.bottom-center {
                                top: 196px;
                                left: 50%;
                                transform: translateX(-50%);
                                .ani-icon-name {
                                    bottom: -16px;
                                }
                            }
                            &.bottom-right-top {
                                top: 45px;
                                right: 160px;
                            }
                            &.bottom-right {
                                top: 186px;
                                right: 100px;
                            }
                            .ani-icon-name {
                                @include elHide();
                            }
                        }
                        .line-dot-red {
                            position: absolute;
                            display: inline-block;
                            bottom: 45px;
                            .line-dot-view {
                                display: inline-block;
                                background-repeat: repeat;
                                background-size: 10px 10px;
                                background-image: url('../../images/ko/showroom/srcomm/bg-line-dot-scarlet.png');
                            }
                            &.center-width {
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                                &.center-width-left {
                                    left: 200px;
                                }
                                &.center-width-right {
                                    right: 200px;
                                }
                                &.center-width-left-top {
                                    left: 247px;
                                    bottom: 185px;
                                    transform: rotate(41deg);
                                    transform-origin: 0 0;
                                }
                                &.center-width-right-top {
                                    right: 247px;
                                    bottom: 185px;
                                    transform: rotate(-41deg);
                                    transform-origin: 100% 0;
                                }
                            }
                            &.center-bottom-top {
                                left: 50%;
                                transform: translate(-50%);
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                            }
                        }
                    }
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            position: absolute;
                            width: 96px;
                            height: 184px;
                            .sr-person-dm-inner {
                                position: relative;
                                .icon-ex-mark-speech-bubble {
                                    position: absolute;
                                    top: -24.92px;
                                    right: -46.94px;
                                }
                            }
                        }
                        .img-dispatch-vehicle {
                            position: absolute;
                        }
                    }
                    .animation-box-inner {
                        position: relative;
                        width: 100%;
                        height: 100%;
                        > div:not(.top-center) {
                            width: 170px;
                            height: 100px;
                            display: flex;
                            align-items: flex-end;
                            justify-content: center;
                        }
                    }
                }
                .bottom-text-wrap {
                    display: block;
                    position: absolute;
                    left: 115px;
                    right: 115px;
                    text-align: center;
                    .text {
                        display: inline-block;
                        font-family: 'Pretendard';
                        font-size: 26px;
                        font-weight: 400;
                        line-height: 130%;
                        letter-spacing: -0.3px;
                        color: rgba(255, 255, 255, 1);
                        .color-blue {
                            font-family: 'Pretendard';
                            font-size: 26px;
                            font-weight: 700;
                            letter-spacing: -0.3px;
                            color: rgba(43, 158, 255, 1);
                        }
                    }
                }
            }

            .bottom-text-wrap {
                bottom: 0px;
                opacity: 0;
                visibility: hidden;
                transition-duration: 0.6s;
            }

            .animation-box-wrap {
                &.control-center {
                    .icon-postion-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                    }

                    .ellipse-wave-length-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                        .ellipse-wave-item {
                            animation-timing-function: linear;
                            animation-duration: 1s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                    }

                    .line-dot-red {
                        .line-dot-view {
                            animation-timing-function: linear;
                            animation-direction: normal;
                            animation-iteration-count: infinite;
                        }
                        &.center-width {
                            width: 0px;
                            height: 2px;
                            transition-duration: 0s;
                            &.center-width-left {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                            &.center-width-left-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                        }
                        &.center-bottom-top {
                            width: 2px;
                            height: 0px;
                            transition-duration: 0s;
                            .line-dot-view {
                                animation-duration: 3s;
                                background-position: center 100%;
                            }
                        }
                    }
                }
                &.dispatch-immediately {
                    overflow: hidden;
                    .sr-person-dm-wrap {
                        opacity: 0;
                        visibility: hidden;
                        top: 130.92px;
                        left: 279.5px;
                        width: 96px;
                        height: 184px;
                    }
                    .icon-ex-mark-speech-bubble {
                        opacity: 0;
                        visibility: hidden;
                    }
                    .img-dispatch-vehicle {
                        opacity: 0;
                        visibility: hidden;
                        top: 159.67px;
                        left: 500px;
                        .di-car-siren-machine {
                            top: 18.07px;
                            left: 172.56px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-siren-light {
                            top: 0px;
                            left: 109.54px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-body {
                            top: 33.27px;
                            left: 0.45px;
                            animation-timing-function: linear;
                            animation-duration: 2s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-exhaust {
                            .di-car-exhaust-bar {
                                left: -100%;
                                animation-timing-function: linear;
                                animation-duration: 1s;
                                animation-direction: normal;
                                animation-iteration-count: infinite;
                            }
                            &.di-car-exhaust1 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0s;
                                }
                            }
                            &.di-car-exhaust2 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0.1s;
                                }
                            }
                        }
                    }
                }
            }

            // .popup-layer-animation-wrap에 active시 동작하나 이것을 페이지 step을 타고 걸어주면 된다.
            &.active {
                opacity: 1;
                visibility: unset;
                pointer-events: unset;
                transition-duration: 0.5s;
                .bottom-text-wrap {
                    bottom: 60px;
                    opacity: 1;
                    visibility: unset;
                    transition-delay: 0.5s;
                }
                .animation-box-wrap {
                    // 에스원 관제센터 active
                    &.control-center {
                        .icon-postion-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 0.3s;
                            &.bottom-left {
                                transition-delay: 1s;
                            }
                            &.bottom-right {
                                transition-delay: 1s;
                            }
                            &.bottom-left-top {
                                transition-delay: 1s;
                            }
                            &.bottom-right-top {
                                transition-delay: 1s;
                            }
                            &.bottom-center {
                                transition-delay: 1.5s;
                            }
                            &.top-center {
                                transition-delay: 2s;
                            }
                        }

                        .ellipse-wave-length-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 1s;
                            &.ellipse-wave-length-wrap1 {
                                transition-delay: 2.5s;
                            }
                            &.ellipse-wave-length-wrap2 {
                                transition-delay: 2.5s;
                            }
                            .ellipse-wave-item {
                                transform: translate(-50%, -50%) scale(0);
                                animation-delay: 3s;
                                animation-name: ellipseWaveItem1;
                            }
                        }

                        .line-dot-red {
                            &.center-width {
                                width: 213px;
                                height: 2px;
                                transition-delay: 3s;
                                transition-duration: 1s;
                                &.center-width-left {
                                    .line-dot-view {
                                        animation-name: centerWidthLeft;
                                    }
                                }
                                &.center-width-right {
                                    .line-dot-view {
                                        animation-name: centerWidthRight;
                                    }
                                }
                            }
                            &.center-bottom-top {
                                width: 2px;
                                height: 98px;
                                transition-delay: 3.5s;
                                transition-duration: 1s;
                                .line-dot-view {
                                    animation-name: centerBottomTop;
                                }
                            }
                        }
                    }

                    // 즉시 현장으로 출동 active
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            opacity: 1;
                            visibility: unset;
                            left: 179.5px;
                            transition-delay: 3s;
                            transition-duration: 1s;
                        }
                        .icon-ex-mark-speech-bubble {
                            opacity: 1;
                            visibility: unset;
                            transition-delay: 2s;
                            transition-duration: 1s;
                        }
                        .img-dispatch-vehicle {
                            opacity: 1;
                            visibility: unset;
                            left: 287.53px;
                            transition-delay: 4s;
                            transition-duration: 0.5s;
                            .di-car-siren-light {
                                animation-name: diCarSirenLight;
                            }
                            .di-car-exhaust {
                                .di-car-exhaust-bar {
                                    animation-name: diCarExhaust;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
