.wrap-online-showroom {
    .showroom-container-wrap {
        &.sr0-main {
            background-color: rgba(226, 226, 226, 1);
            .title-pa {
                position: absolute;
                top: 146px;
                left: 127px;
            }
        }
        .showroom-container-inner {
            .showroom-content-wrap {
                &.showroom-main {
                    @include bgCenterSet;
                    top: 60%;
                    left: 57%;
                    width: 1530px;
                    height: 966px;
                    transform: translate(-50%, -50%);
                    // background-image: url('../../images/ko/showroom/sr0/bg_s1_showroom_intro_pc.png');
                }
            }
        }
    }

    .unit-select-wrap {
        @include bgCenterSet;
        display: block;
        position: absolute;
        width: 354px;
        height: 348px;
        background-color: rgba(0, 0, 0, 0);

        .hover-bg {
            @include bgCenterSet;
            position: absolute;
            left: 0;
            bottom: 0;
            display: block;
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
            transition-duration: 0.3s;
        }

        &:hover {
            .hover-bg,
            .speech-bubble-wrap {
                opacity: 1;
                visibility: unset;
                pointer-events: unset;
            }
        }

        // 1_단독주택(가정용)
        &.unit-select-wrap1 {
            top: 594px;
            left: 66px;
            width: 320px;
            height: 179px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr1_normal.png');
            .title-sign {
                top: -42px;
                left: 54%;
            }
        }

        // 2_공동주택(가정용)
        &.unit-select-wrap2 {
            top: 253px;
            left: 0;
            width: 374px;
            height: 316px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr2_normal.png');
            .title-sign {
                top: -74px;
                left: 38%;
            }
        }

        // 3_매장(상업용)
        &.unit-select-wrap3 {
            top: 425px;
            left: 396px;
            width: 352px;
            height: 271px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr3_normal.png');
            z-index: 1;
            transition-duration: 0.3s;
            &:hover {
                background-image: url('../../images/ko/showroom/sr0/btn_sr3_hover.png');
                .speech-bubble-wrap {
                    // top: 99px;
                    // left: 59%;
                }
            }
            .title-sign {
                top: -62px;
                left: 43%;
            }
        }

        // 4_사무실(상업용)
        &.unit-select-wrap4 {
            top: 157px;
            left: 697px;
            width: 408px;
            height: 414px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr4_normal.png');
            .title-sign {
                top: -63px;
                left: 32%;
            }
        }

        // 5_공장(상업용)
        &.unit-select-wrap5 {
            top: 619px;
            left: 635px;
            width: 638px;
            height: 348px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr5_normal.png');
            .title-sign {
                top: -8px;
                left: 23%;
            }
        }

        // 6_창고(상업용)
        &.unit-select-wrap6 {
            top: 445px;
            left: 1051px;
            width: 480px;
            height: 274px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr6_normal.png');
            .title-sign {
                top: -46px;
                left: 59%;
            }
        }

        // 7_도어캠

        // 8_블루스캔
        &.unit-select-wrap8 {
            top: 93px;
            left: 1010px;
            width: 398px;
            height: 319px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr8_normal.png');
            transition-duration: 0.3s;
            &:hover {
                background-image: url('../../images/ko/showroom/sr0/btn_sr8_hover.png');
                .speech-bubble-wrap {
                    top: 100px;
                    left: 52%;
                }
            }
            .title-sign {
                top: -76px;
                left: 25%;
            }
            .speech-bubble-wrap {
                top: 100px;
                left: 47%;
            }
        }

        // 9_PM/FM
        &.unit-select-wrap9 {
            top: 1px;
            left: 329px;
            width: 408px;
            height: 433px;
            background-image: url('../../images/ko/showroom/sr0/btn_sr9_normal.png');
            &:hover {
                .speech-bubble-wrap {
                    top: 95px;
                    left: 34%;
                }
            }
            .title-sign {
                top: -66px;
                left: 31%;
            }
            .speech-bubble-wrap {
                top: 95px;
                left: 29%;
            }
        }

        .unit-select-inner {
            display: block;
            position: relative;
            width: 100%;
            height: 100%;
        }
    }
}
