// [사무실] : /showroom/office.html

.sr4-office {
    .showroom-content-mark {
        border: 0 !important;
    }

    // [사무실] .sr4-office Start
    background-color: rgb(226, 226, 226);
    &.screen1 {
        &.step2 {
            background-color: #c2c4c8;
        }
        &.step3-1 {
            background-color: #c2c4c8;
        }
    }
    &.screen2 {
        &.step2,
        &.step3 {
            background-color: #c2c4c8;
        }
    }

    // 우측 스텝 메뉴 초기셋팅
    .service-step-wrap {
        @include elHide();
        top: 52%;
        .service-step-inner {
            &::after {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                display: block;
                content: '';
                background-repeat: no-repeat;
                background-position: center center;
                background-size: 100% 100%;
                background-color: rgba(0, 0, 0, 0.75);
                filter: blur(0px);
                transition-delay: 0s;
                transition-duration: 0s;
                @include elHide();
                border-radius: 20px;
            }
        }
    }

    // 출동경비 서비스 0911 팝업
    .popup-layer-animation-wrap-1 {
        &.popup-layer-animation-wrap {
            display: inline-block;
            border-radius: 20px;
            width: 820px;
            height: 490px;
            margin-left: auto;
            margin-right: auto;
            font-size: 0;

            .popup-layer-animation-inner {
                display: inline-block;
                position: relative;
                width: inherit;
                height: inherit;
                font-size: 0;
                border-radius: inherit;
                overflow: hidden;
                &::before {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    width: 120%;
                    height: 120%;
                    transform: translate(-50%, -50%);
                    display: block;
                    content: '';
                    background-color: rgba(36, 36, 36, 0.95);
                    filter: blur(10px);
                }
                .animation-box-wrap {
                    position: absolute;
                    top: 0;
                    left: 0;
                    right: 0;
                    height: 318px;
                    font-size: 0;
                    &.control-center {
                        .icon-postion-wrap {
                            position: absolute;
                            z-index: 1;
                            .icon-postion-inner {
                                position: relative;
                                .ani-icon-secom {
                                    position: relative;
                                    z-index: 1;
                                }
                                .ellipse-wave-length-wrap {
                                    left: 50%;
                                    transform: translateX(-50%);
                                    &.ellipse-wave-length-wrap1 {
                                        // bottom: -6px;
                                    }
                                    &.ellipse-wave-length-wrap2 {
                                        bottom: -14px;
                                    }
                                }
                            }
                            &.top-center {
                                top: 55.04px;
                                left: 50%;
                                transform: translateX(-50%);
                            }
                            &.bottom-left {
                                top: 185px;
                                left: 100px;
                            }
                            &.bottom-left-top {
                                top: 45px;
                                left: 160px;
                            }
                            &.bottom-center {
                                top: 196px;
                                left: 50%;
                                transform: translateX(-50%);
                                .ani-icon-name {
                                    bottom: -16px;
                                }
                            }
                            &.bottom-right-top {
                                top: 45px;
                                right: 160px;
                            }
                            &.bottom-right {
                                top: 186px !important;
                                right: 100px;
                            }
                            .ani-icon-name {
                                @include elHide();
                            }
                        }
                        .line-dot-red {
                            position: absolute;
                            display: inline-block;
                            bottom: 45px;
                            .line-dot-view {
                                display: inline-block;
                                background-repeat: repeat;
                                background-size: 10px 10px;
                                background-image: url('../../images/ko/showroom/srcomm/bg-line-dot-scarlet.png');
                            }
                            &.center-width {
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                                &.center-width-left {
                                    left: 200px;
                                }
                                &.center-width-right {
                                    right: 200px;
                                }
                                &.center-width-left-top {
                                    left: 247px;
                                    bottom: 185px;
                                    transform: rotate(41deg);
                                    transform-origin: 0 0;
                                }
                                &.center-width-right-top {
                                    right: 247px;
                                    bottom: 185px;
                                    transform: rotate(-41deg);
                                    transform-origin: 100% 0;
                                }
                            }
                            &.center-bottom-top {
                                left: 50%;
                                transform: translate(-50%);
                                .line-dot-view {
                                    width: 100%;
                                    height: 100%;
                                }
                            }
                        }
                    }
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            position: absolute;
                            width: 96px;
                            height: 184px;
                            .sr-person-dm-inner {
                                position: relative;
                                .icon-ex-mark-speech-bubble {
                                    position: absolute;
                                    top: -24.92px;
                                    right: -46.94px;
                                }
                            }
                        }
                        .img-dispatch-vehicle {
                            position: absolute;
                        }
                    }
                    .animation-box-inner {
                        position: relative;
                        width: 100%;
                        height: 100%;
                        > div:not(.top-center) {
                            width: 170px;
                            height: 100px;
                            display: flex;
                            align-items: flex-end;
                            justify-content: center;
                        }
                    }
                }
                .bottom-text-wrap {
                    display: block;
                    position: absolute;
                    left: 115px;
                    right: 115px;
                    text-align: center;
                    .text {
                        display: inline-block;
                        font-family: 'Pretendard';
                        font-size: 26px;
                        font-weight: 400;
                        line-height: 130%;
                        letter-spacing: -0.3px;
                        color: rgba(255, 255, 255, 1);
                        .color-blue {
                            font-family: 'Pretendard';
                            font-size: 26px;
                            font-weight: 700;
                            letter-spacing: -0.3px;
                            color: rgba(43, 158, 255, 1);
                        }
                    }
                }
            }

            .bottom-text-wrap {
                bottom: 0px;
                opacity: 0;
                visibility: hidden;
                transition-duration: 0.6s;
            }

            .animation-box-wrap {
                &.control-center {
                    .icon-postion-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                    }

                    .ellipse-wave-length-wrap {
                        opacity: 0;
                        visibility: hidden;
                        transition-duration: 0s;
                        .ellipse-wave-item {
                            animation-timing-function: linear;
                            animation-duration: 1s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                    }

                    .line-dot-red {
                        .line-dot-view {
                            animation-timing-function: linear;
                            animation-direction: normal;
                            animation-iteration-count: infinite;
                        }
                        &.center-width {
                            width: 0px;
                            height: 2px;
                            transition-duration: 0s;
                            &.center-width-left {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                            &.center-width-left-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 0% center;
                                }
                            }
                            &.center-width-right-top {
                                .line-dot-view {
                                    animation-duration: 4s;
                                    background-position: 100% center;
                                }
                            }
                        }
                        &.center-bottom-top {
                            width: 2px;
                            height: 0px;
                            transition-duration: 0s;
                            .line-dot-view {
                                animation-duration: 3s;
                                background-position: center 100%;
                            }
                        }
                    }
                }
                &.dispatch-immediately {
                    overflow: hidden;
                    .sr-person-dm-wrap {
                        opacity: 0;
                        visibility: hidden;
                        top: 130.92px;
                        left: 279.5px;
                        width: 96px;
                        height: 184px;
                    }
                    .icon-ex-mark-speech-bubble {
                        opacity: 0;
                        visibility: hidden;
                    }
                    .img-dispatch-vehicle {
                        opacity: 0;
                        visibility: hidden;
                        top: 159.67px;
                        left: 500px;
                        .di-car-siren-machine {
                            top: 18.07px;
                            left: 172.56px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-siren-light {
                            top: 0px;
                            left: 109.54px;
                            animation-timing-function: linear;
                            animation-duration: 1.5s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-body {
                            top: 33.27px;
                            left: 0.45px;
                            animation-timing-function: linear;
                            animation-duration: 2s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                        .di-car-exhaust {
                            .di-car-exhaust-bar {
                                left: -100%;
                                animation-timing-function: linear;
                                animation-duration: 1s;
                                animation-direction: normal;
                                animation-iteration-count: infinite;
                            }
                            &.di-car-exhaust1 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0s;
                                }
                            }
                            &.di-car-exhaust2 {
                                .di-car-exhaust-bar {
                                    animation-delay: 0.1s;
                                }
                            }
                        }
                    }
                }
            }

            // .popup-layer-animation-wrap에 active시 동작하나 이것을 페이지 step을 타고 걸어주면 된다.
            &.active {
                opacity: 1;
                visibility: unset;
                pointer-events: unset;
                transition-duration: 0.5s;
                .bottom-text-wrap {
                    bottom: 60px;
                    opacity: 1;
                    visibility: unset;
                    transition-delay: 0.5s;
                }
                .animation-box-wrap {
                    // 에스원 관제센터 active
                    &.control-center {
                        .icon-postion-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 0.3s;
                            &.bottom-left {
                                transition-delay: 1s;
                            }
                            &.bottom-right {
                                transition-delay: 1s;
                            }
                            &.bottom-left-top {
                                transition-delay: 1s;
                            }
                            &.bottom-right-top {
                                transition-delay: 1s;
                            }
                            &.bottom-center {
                                transition-delay: 1.5s;
                            }
                            &.top-center {
                                transition-delay: 2s;
                            }
                        }

                        .ellipse-wave-length-wrap {
                            opacity: 1;
                            visibility: unset;
                            transition-duration: 1s;
                            &.ellipse-wave-length-wrap1 {
                                transition-delay: 2.5s;
                            }
                            &.ellipse-wave-length-wrap2 {
                                transition-delay: 2.5s;
                            }
                            .ellipse-wave-item {
                                transform: translate(-50%, -50%) scale(0);
                                animation-delay: 3s;
                                animation-name: ellipseWaveItem1;
                            }
                        }

                        .line-dot-red {
                            &.center-width {
                                width: 213px;
                                height: 2px;
                                transition-delay: 3s;
                                transition-duration: 1s;
                                &.center-width-left {
                                    .line-dot-view {
                                        animation-name: centerWidthLeft;
                                    }
                                }
                                &.center-width-right {
                                    .line-dot-view {
                                        animation-name: centerWidthRight;
                                    }
                                }
                            }
                            &.center-bottom-top {
                                width: 2px;
                                height: 98px;
                                transition-delay: 3.5s;
                                transition-duration: 1s;
                                .line-dot-view {
                                    animation-name: centerBottomTop;
                                }
                            }
                        }
                    }

                    // 즉시 현장으로 출동 active
                    &.dispatch-immediately {
                        .sr-person-dm-wrap {
                            opacity: 1;
                            visibility: unset;
                            left: 179.5px;
                            transition-delay: 3s;
                            transition-duration: 1s;
                        }
                        .icon-ex-mark-speech-bubble {
                            opacity: 1;
                            visibility: unset;
                            transition-delay: 2s;
                            transition-duration: 1s;
                        }
                        .img-dispatch-vehicle {
                            opacity: 1;
                            visibility: unset;
                            left: 287.53px;
                            transition-delay: 4s;
                            transition-duration: 0.5s;
                            .di-car-siren-light {
                                animation-name: diCarSirenLight;
                            }
                            .di-car-exhaust {
                                .di-car-exhaust-bar {
                                    animation-name: diCarExhaust;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    .ani-icon-secom {
        display: inline-block;
        background-repeat: no-repeat;
        background-position: center center;
        background-size: contain;
        // 링크
        &-link {
            width: 100px;
            height: 50px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-center-pop.svg');
        }
        // 열선 감지기
        &-heat-detector {
            width: 58px;
            height: 120px;
            background-image: url('../../images/ko/showroom/sr4/img-pro-01.svg');
        }
        // 움직임 감지기
        &-glass-detector {
            width: 100px;
            height: 115px;
            background-image: url('../../images/ko/showroom/sr4/img-pro-02.svg');
            display: inline-block;
            background-repeat: no-repeat;
            background-position: center;
            position: relative;
            z-index: 1;
        }
        // 문열림 감지기
        &-magnet-detector {
            bottom: 10px;
            width: 126px;
            height: 39px;
            background-image: url('../../images/ko/showroom/sr4/img-pro-03.svg');
        }
        // 적외선 감지기
        &-infrared-detector {
            width: 30.12px;
            height: 81.57px;
            background-image: url('../../images/ko/showroom/srcomm/img-pro-04.svg');
            bottom: 8px;
            display: inline-block;
            position: absolute;
            z-index: 30;
            left: -15px;
        }
        // 금고 감지기
        &-safe-sensor {
            width: 55px;
            height: 76px;
            background-image: url('../../images/ko/showroom/sr4/img-pro-05.svg');
            bottom: 11px;
            left: -2px;
        }
    }
    // 출동경비 서비스 0911 팝업

    // [사무실] 컨텐츠 showroom-content-wrap4
    .showroom-content-wrap4 {
        width: 1920px;
        height: 1080px;
        top: 50%;
        left: 50%;
        z-index: 3;
    }

    // 스크린 공통
    .showroom-screen-wrap {
        @include elHide();
    }

    // 제품 감지기 출동경비서비스 움직임 감지 추가
    .sr-pro-sensor {
        width: 29px;
        height: 53px;
        position: absolute;
        left: 945px;
        top: 696px;
        background: url(../../images/ko/showroom/sr4/img-safe-box.svg) no-repeat center 100%;
        @include elHide();
        background-size: 100%;
    }
    // 금고 이미지
    .sr-safe-box {
        width: 169px;
        height: 199px;
        position: absolute;
        left: 932px;
        top: 630px;
        background: url(../../images/ko/showroom/sr4/img-sr4-safe-box.svg) no-repeat center 100%;
        @include elHide();
        background-size: 100%;
    }
    // 스텝 공통
    .showroom-step-wrap {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 100%;
        height: 100%;
        @include elHide();
        transition-duration: 1s;
    }

    // 스텝 안 공통
    .showroom-step-inner {
        position: relative;
        width: 100%;
        height: 100%;
    }

    // 배경 : 인테리어, 딤 기본설정
    .showroom-background {
        // 이미지
        &-area {
            position: absolute;
            width: 1920px;
            height: 1080px;
            top: 50%;
            left: 50%;
        }
        &-inner {
            position: relative;
            width: inherit;
            height: inherit;
        }
        // 배경 인테리어
        &-layer {
            position: absolute;
            background-image: url('../../images/ko/showroom/sr4/bg-sr4-interior0-1.jpg');
            transform: scale(1);
            @include elHide();
            transition-duration: 0.6s;
        }
        // 딤 : 배경 어둠/밝기
        &-dim {
            background-image: url('../../images/ko/showroom/sr4/bg-sr4-dimm0-1.png');
            @include elHide();
        }
    }

    // 메인 포인터
    .sr-pointer-wrap {
        position: absolute;
        @include elHide();

        &.sr-pointer-wrap1 {
            top: 383px;
            right: 578px;
        }
        &.sr-pointer-wrap2 {
            top: 442px;
            left: 342px;
        }
        &.sr-pointer-wrap3 {
            top: 602px;
            left: 535.5px;
        }
        .sr-pointer-layer {
            [class*='sr-pointer-layer-'] {
                animation-delay: 0s;
                animation-play-state: running;
            }
        }
        .sr-pointer-inner {
            position: relative;
        }
        .sr-pointer-tip-wrap {
            position: absolute;
            left: 50%;
            bottom: -63px;
            transform: translateX(-50%);
            .sr-pointer-tip-inner {
                position: relative;
                text-align: center;
                padding-top: 23px;
                .box-text {
                    display: inline-block;
                    background-color: rgba(255, 255, 255, 1);
                    white-space: nowrap;
                    font-family: 'Pretendard';
                    font-weight: 700;
                    font-size: 18px;
                    line-height: 1;
                    letter-spacing: -0.3px;
                    color: #000000;
                    text-align: center;
                    padding: 13px 24px;
                    border-radius: 22px;
                }
                .triangle-top {
                    position: absolute;
                    top: 0;
                    left: 50%;
                    transform: translateX(-50%);
                    width: 0px;
                    height: 0px;
                    border-bottom: 14px solid rgb(255, 255, 255);
                    border-left: 8px solid transparent;
                    border-right: 8px solid transparent;
                }
            }
        }
        &.check-complete {
            transition-delay: 0s !important;
            transition-duration: 0s !important;
            opacity: 0 !important;
            visibility: hidden !important;
            pointer-events: none !important;
        }
    }

    // 안심
    .popup-check-complete-wrap {
        position: absolute;
        z-index: 25;
        @include elHide();
        &.popup-check-complete-wrap1 {
            top: 265px;
            left: 1153px;
        }
        &.popup-check-complete-wrap2 {
            top: 325px;
            left: 178px;
        }
        &.popup-check-complete-wrap3 {
            bottom: 247px;
            left: 480px;
        }
        &.check-complete {
            transition-delay: 1s;
            transition-duration: 1s;
            @include elShow();
        }
    }

    // 스와이퍼
    .swiper-layer-wrap {
        &.swiper-layer-wrap1 {
            .thumbnail-wrap {
                &.thumbnail-wrap1 {
                    background-image: url('../../images/ko/showroom/thumbnail/s1-sr4-office-sc1.jpg');
                }
                // &.thumbnail-wrap2 {
                //     background-image: url('../../images/ko/showroom/srcomm/sc-sec-swiper1-2.jpg');
                // }
                // &.thumbnail-wrap3 {
                //     background-image: url('../../images/ko/showroom/srcomm/sc-sec-swiper1-3.jpg');
                // }
            }
        }
        &.swiper-layer-wrap2 {
            .thumbnail-wrap {
                &.thumbnail-wrap1 {
                    background-image: url(../../images/ko/showroom/thumbnail/sr-cctv-item02-02.jpg);
                }
                &.thumbnail-wrap2 {
                    background-image: url(../../images/ko/showroom/sr4/screen2Swiper2-2.jpg);
                }
                &.thumbnail-wrap3 {
                    background-image: url(../../images/ko/showroom/thumbnail/sr-cctv-item02-01.jpg);
                }
            }
        }
    }

    // 스와이퍼 썸네일 이미지 버튼 눌렀을 경우 안보이게
    .iframe-video.active + .thumbnail-wrap {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }
    &.default {
        // 배경 : 인테리어, 딤 기본설정
        .showroom-background {
            // 이미지
            &-area {
                position: absolute;
                width: 1920px;
                height: 1080px;
                top: 50%;
                left: 50%;
            }
            &-inner {
                position: relative;
                width: inherit;
                height: inherit;
            }
            // 배경 인테리어
            &-layer {
                @include bgCenterSet;
                top: 72px;
                left: -6px;
                width: 2246.28px;
                height: 1078.72px;
                background-image: url('../../images/ko/showroom/sr4/bg-sr4-interior0-1.jpg');
                transform: scale(1);
                filter: blur(10px);
                @include elHide();
            }
            // 딤 : 배경 어둠/밝기
            &-dim {
                background-image: url('../../images/ko/showroom/sr4/bg-sr4-dimm0-1.png');
                @include elHide();
            }
        }

        // 메인 포인터
        .sr-pointer-wrap {
            @include elHide();
        }
    }

    // 카테고리의 메인
    &.main {
        &.end-page {
            .showroom-background-dim {
                transition-delay: 0s;
                transition-duration: 1s;
                @include elHide();
            }
        }
        .showroom-background {
            // 배경 인테리어
            &-layer {
                @include bgCenterSet;
                top: 72px;
                left: -6px;
                width: 2246.28px;
                height: 1078.72px;
                background-image: url('../../images/ko/showroom/sr4/bg-sr4-interior0-1.jpg');
                transform: scale(1);
                filter: blur(0px);
                @include elShow();
                transition-duration: 1.5s;
            }
            // 딤 : 배경 어둠/밝기
            &-dim {
                background-image: url('../../images/ko/showroom/sr4/bg-sr4-dimm0-1.png');
                @include elShow();
                transition-delay: 1s;
                transition-duration: 1s;
            }
        }

        .showroom-screen0-wrap {
            @include elShow();
            .showroom-step1-wrap {
                @include elShow();
            }
        }

        // 메인 : 적색 포인터
        .sr-pointer-wrap {
            transition-delay: 1s;
            transition-duration: 1s;
            @include elShow();
        }
    }

    // 모든 스크린 공통
    &.screen1,
    &.screen2,
    &.screen3 {
